/* eslint-disable arrow-body-style */
/* eslint-disable no-console */
/* eslint-disable no-param-reassign */
/* eslint-disable consistent-return */
import React from 'react'
import { fetchReplayData, VideoContentReplayError } from './utils'
import { DOMChanges, DOMChangesMin, IVideoInterface } from './types'
import SessionReplay from './SessionReplay'

interface ReplayGesture {
	start: number
	end: number
}

// Skip inactivity constants (matching mobile behavior)
const MIN_REPLAY_TIME_BEFORE = 2 // seconds to show before gesture
const MIN_REPLAY_TIME_AFTER = 2  // seconds to show after gesture
const MIN_SKIP_DURATION = 3      // minimum gap (seconds) to trigger skip

const ReplayComponent: React.FC<{
  videoRef?: React.MutableRefObject<IVideoInterface | undefined>;
  src: string;
  autoPlay?: boolean;
  skipInactivity?: boolean;
  heatmap?: {
	time: number;
  };
  preventDestroy?: boolean;
  trailOpacity?: number;
  trailThicknessRatio?: number;
}> = ( {
	videoRef,
	src,
	autoPlay = false,
	skipInactivity = false,
	heatmap,
	preventDestroy = false,
	trailOpacity,
	trailThicknessRatio,
} ) => {
	const autoPlayRef = React.useRef( autoPlay )

	React.useEffect( () => {
		autoPlayRef.current = autoPlay
	}, [ autoPlay ] )

	const [ sessionData, setSessionData ] = React.useState<( DOMChanges | DOMChangesMin )[]>()
	const [ isVideoContent, setIsVideoContent ] = React.useState( false )

	const gestures: ReplayGesture[] = React.useMemo( () => {
		if ( !sessionData ) { return [] }

		// Get duration from the last change (sorted by sequence)
		const lastChange = sessionData[sessionData.length - 1]
		let sessionDuration = Infinity
		if (lastChange) {
			const lastChangeTime = typeof (lastChange as DOMChanges).time === 'number'
				? (lastChange as DOMChanges).time
				: (lastChange as DOMChangesMin).t
			sessionDuration = lastChangeTime / 1000
		}

		const result = sessionData
			.filter( ( change ) => !SessionReplay.isChangeSkippable( change ) )
			.map( ( change ) => {
				const time = typeof ( change as DOMChanges ).time === 'number' ? ( change as DOMChanges ).time : ( change as DOMChangesMin ).t

				return {
					start: time / 1000,
					end: time / 1000 + 0.5,
				}
			} )
			// Filter out gestures with invalid timestamps (beyond session duration)
			.filter( ( gesture ) => gesture.start <= sessionDuration + 1 )
			// Sort by start time (critical for skip logic!)
			.sort( ( a, b ) => a.start - b.start )

		return result
	}, [ sessionData ] )

	React.useEffect(() => {
		setIsVideoContent( false )
		fetchReplayData( src )
			.then( ( data ) => setSessionData( SessionReplay.sortChanges( data ) ) )
			.catch( ( err ) => {
				if ( err instanceof VideoContentReplayError ) {
					setIsVideoContent( true )
					return
				}
				console.error( 'Failed to load replay data', err )
			} )
	}, [ src ])

	const [ container, setContainer ] = React.useState<HTMLDivElement>()
	const containerRef = React.useRef<HTMLDivElement>() as React.MutableRefObject<HTMLDivElement>

	React.useEffect( () => {
		setContainer(containerRef.current)
	}, [ containerRef ] )


	const replayInstance = React.useMemo( () => {
		return new SessionReplay( {
			heatmap,
			trailOpacity,
			trailThicknessRatio,
		} )
	// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [ src, trailOpacity, trailThicknessRatio, heatmap ] )

	React.useEffect( () => {
		if ( !container ) { return }
		if ( !replayInstance ) { return }
		replayInstance.setContainer( container )
	}, [ container, replayInstance ] )

	React.useEffect( () => {

	if ( !replayInstance ) { return }
	if ( videoRef ) {
		videoRef.current = replayInstance
	}
	return () => {
		if ( preventDestroy ) { return }
		replayInstance.destroy()
		if ( videoRef ) {
			videoRef.current = undefined
		}
	}

	}, [ replayInstance, videoRef, preventDestroy ] )

	React.useEffect( () => {
	if ( !replayInstance ) { return }
	if ( !sessionData ) { return }

	replayInstance.loadDomChanges( sessionData )
	if ( autoPlayRef.current ) {
		console.log( 'Replay Components .play()' )
		replayInstance.play()
	}

	}, [ replayInstance, sessionData ] )

	React.useEffect( () => {

		if ( !skipInactivity ) { return }
		if ( !replayInstance ) { return }

		// eslint-disable-next-line no-undef
		let timeout: NodeJS.Timeout | null = null

		const checkAnimationTime = () => {
			const { currentTime, duration } = replayInstance

			// eslint-disable-next-line no-plusplus
			for ( let i = 0; i < gestures.length; i++ ) {
				const gesture = gestures[i]
				const windowStart = Math.max( 0, gesture.start - MIN_REPLAY_TIME_BEFORE )
				const windowEnd = gesture.end + MIN_REPLAY_TIME_AFTER

				// Past this gesture's window - continue to next
				if ( currentTime > windowEnd ) {
					if ( i === gestures.length - 1 ) {
						// Past all gestures - skip to end
						replayInstance.currentTime = duration
						return
					}
					// eslint-disable-next-line no-continue
					continue
				}

				// Within this gesture's window - don't skip
				if ( currentTime >= windowStart ) {
					timeout = setTimeout( checkAnimationTime, 200 )
					return
				}

				// Before this gesture - check if we should skip
				const timeToGesture = gesture.start - currentTime
				if ( timeToGesture > MIN_SKIP_DURATION ) {
					replayInstance.currentTime = Math.max( 0, gesture.start - MIN_REPLAY_TIME_BEFORE )
				}
				timeout = setTimeout( checkAnimationTime, 200 )
				return
			}

			// No gestures at all - just keep playing
			timeout = setTimeout( checkAnimationTime, 200 )
		}

		const handlePlay = () => {
			timeout = setTimeout( checkAnimationTime, 200 )
		}

		const handlePause = () => {
			if ( timeout ) {
				clearInterval( timeout )
			}
		}

		replayInstance.addEventListener( 'play', handlePlay )
		replayInstance.addEventListener( 'pause', handlePause )
		replayInstance.addEventListener( 'ended', handlePause )

		if ( !replayInstance.paused && !replayInstance.ended ) {
			checkAnimationTime()
		}

		return () => {
			if ( timeout ) {
				clearTimeout( timeout )
			}
			replayInstance.removeEventListener( 'play', handlePlay )
			replayInstance.removeEventListener( 'pause', handlePause )
			replayInstance.removeEventListener( 'ended', handlePause )
		}

	}, [ replayInstance, gestures, skipInactivity ] )

	if ( isVideoContent ) {
		return (
			<div
				style={ {
					display: 'flex',
					alignItems: 'center',
					justifyContent: 'center',
					width: '100%',
					height: '100%',
					padding: '24px',
					textAlign: 'center',
					color: '#666',
					fontSize: '14px',
				} }
			>
				Heatmaps are not supported for Flutter Web.
			</div>
		)
	}

	return (
		<div
			ref={ containerRef }
		/>
	)
}

export default ReplayComponent
