import React, { useCallback, useMemo, memo } from 'react';
import styled, { createGlobalStyle } from 'styled-components';
import { Space, Dropdown, Menu } from 'antd';
import DropdownIcon from 'public/static/session-replay/dropdown.svg';
import { useSessionVideoContext } from '../../Context';

const GlobalStyle = createGlobalStyle`
    .speed-option-title .ant-dropdown-menu-item-group-title {
        text-align: center;
        color: #151E35;
        padding: 5px 0;
    }
    .speed-option {
        padding: 5px 15px 5px 5px;
    }
`;

const PlaybackSpeed = styled.div`
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 12px;
  gap: 4px;
  color: #090f19;
  border-radius: 50px;
  background-color: #f3f4f5;
  padding: 4px 6px;
  cursor: pointer;
  position: relative;
`;

const StyledMenu = styled(Menu)`
  border-radius: 8px;

  .ant-dropdown-menu-item-group-list {
    margin: 0;
    padding: 0 6px;

    li {
      border-radius: 4px;
    }
  }
`;

const StyledMenuItem = styled(Menu.Item)`
  background-color: ${(props) =>
    props.isSelected ? '#EFF5FF' : 'transparent'};
`;

const Speeds = [0.5, 1, 2, 4];

const SpeedOption = memo(({ speed, isSelected, ...rest }) => (
  // eslint-disable-next-line react/jsx-props-no-spreading
  <StyledMenuItem className="speed-option" {...rest} isSelected={isSelected}>
    {speed}x
  </StyledMenuItem>
));

const VideoPlaybackControls = ({ onPlayrateChange, containerRef }) => {
  const { playbackRate } = useSessionVideoContext();
  const handleSelect = useCallback(
    (itemProps) => {
      onPlayrateChange(itemProps.key);
    },
    [onPlayrateChange]
  );
  const speedViewMenu = useMemo(
    () => (
      <StyledMenu onClick={handleSelect}>
        <Menu.ItemGroup title="" className="speed-option-title">
          {Speeds.map((speed) => (
            <SpeedOption
              key={speed}
              speed={speed}
              isSelected={speed === playbackRate}
            />
          ))}
        </Menu.ItemGroup>
      </StyledMenu>
    ),
    [playbackRate]
  );
  const handleGetContainer = useCallback(
    () => containerRef.current,
    [containerRef]
  );

  return (
    <>
      <GlobalStyle />
      <Space direction="vertical">
        <Dropdown
          getPopupContainer={handleGetContainer}
          overlay={speedViewMenu}
          placement="top"
        >
          <PlaybackSpeed>
            <span>{playbackRate}x</span>
            <DropdownIcon />
          </PlaybackSpeed>
        </Dropdown>
      </Space>
    </>
  );
};

export default memo(VideoPlaybackControls);
