	private __lastMousePos: MouseMoveChange | TouchChange | null = null

	private applyMouseMove = ( change: MouseMoveChange, skipTrail = false ) => {
		if ( this.heatmapConfig ) { return }

		const doc = change.iframeContext
			? this.__iframeMap.get(change.iframeContext)?.contentDocument
			: this.iframe.contentDocument

		if (doc) {
			this.ensureCursorInDocument(doc)
			this.positionCursor(change.x, change.y, doc)
			if (this.mouseElem) {
				this.mouseElem.style.display = 'block'
			}
		}

		if ( this.__lastMousePos && !skipTrail ) {
			const lastCtx = this.__lastMousePos.type === 'MOUSE_MOVE' ? (this.__lastMousePos as MouseMoveChange).iframeContext : undefined
			const { x: lastX, y: lastY } = this.getCursorPositionInContainerSpace(this.__lastMousePos.x, this.__lastMousePos.y, lastCtx)
			const { x: currentX, y: currentY } = this.getCursorPositionInContainerSpace(change.x, change.y, change.iframeContext)
			this.trailPath.push([
				1,
				[lastX, lastY],
				[currentX, currentY],
				2.0,
			])
		}
		this.__lastMousePos = change

		this.drawTrail()
	}


	private drawTrailRequest: number | null = null

	private drawTrail = () => {
		if ( this.paused || this.__finished ) {
			return
		}

		if ( this.drawTrailRequest ) {
			cancelAnimationFrame( this.drawTrailRequest )
		}

		const { trailCanvasCtx } = this
		if ( !trailCanvasCtx ) {
			return
		}
		const { trailPath } = this

		// clear canvas
		trailCanvasCtx.clearRect( 0, 0, this.videoWidth, this.videoHeight )

		for( const trail of trailPath ) {
			switch( trail[0] ) {
				// Mouse trail
				case 1: {
					const useTrail = trail as OverlayTrail
					const [ , [ x1, y1 ], [ x2, y2 ], i ] = useTrail
					if ( i <= 0 ) {
						// remove from list
						const index = trailPath.indexOf( trail )
						trailPath.splice( index, 1 )
						// eslint-disable-next-line no-continue
						continue
					}
					const opacity = ( Math.min( i, this.__trailOpacity ) * 0.5 ).toFixed( 2 )
					trailCanvasCtx.beginPath()
					trailCanvasCtx.lineWidth = 3 * this.__trailThicknessRatio
					trailCanvasCtx.strokeStyle = `rgba(220, 79, 68, ${ opacity })`
					trailCanvasCtx.moveTo( x1, y1 )
					trailCanvasCtx.lineTo( x2, y2 )
					trailCanvasCtx.stroke()
					trailCanvasCtx.closePath()
					useTrail[ 3 ] -= 0.01
					break
				}
				// Click
				case 2: {
					const useClick = trail as OverlayClick
					const [ , [ x, y ], i ] = useClick
					if ( i <= 0 ) {
						// remove from list
						const index = trailPath.indexOf( trail )
						trailPath.splice( index, 1 )
						// eslint-disable-next-line no-continue
						continue
					}
					const opacity = ( Math.min( i, this.__trailOpacity ) * 0.5 ).toFixed( 2 )
					trailCanvasCtx.beginPath()
					trailCanvasCtx.fillStyle = `rgba(220, 79, 68, ${ opacity })`
					trailCanvasCtx.arc(
						x,
						y,
						16 * this.__trailThicknessRatio,
						0,
						2 * Math.PI
					)
					trailCanvasCtx.fill()
					trailCanvasCtx.closePath()
					useClick[ 2 ] -= 0.01
					break
				}
				// Touch trail
				case 3: {
					const useTrail = trail as OverlayTouch
					const [ , [ x1, y1 ], [ x2, y2 ], i ] = useTrail
					if ( i <= 0 ) {
						// remove from list
						const index = trailPath.indexOf( trail )
						trailPath.splice( index, 1 )
						// eslint-disable-next-line no-continue
						continue
					}
					const opacity = ( Math.min( i, this.__trailOpacity ) * 0.5 ).toFixed( 2 )
					trailCanvasCtx.beginPath()
					trailCanvasCtx.lineWidth = 12 * this.__trailThicknessRatio
					trailCanvasCtx.lineCap = 'round'
					trailCanvasCtx.strokeStyle = `rgba(220, 79, 68, ${ opacity })`
					trailCanvasCtx.moveTo( x1, y1 )
					trailCanvasCtx.lineTo( x2, y2 )
					trailCanvasCtx.stroke()
					trailCanvasCtx.closePath()
					useTrail[ 3 ] -= 0.01
					break
				}
				default: {
					// eslint-disable-next-line no-continue
					continue
				}
			}
		}

		this.drawTrailRequest = requestAnimationFrame( this.drawTrail )
	}

