	private applyPageLoad = ( change: PageLoad ) => {

		this.domMap.clear()
		this.reverseDomMap.clear()
        this.clearIframeMaps()
		this.__sheetMap.clear()
		this.registerDocumentNodes()

		const iframeDoc = this.iframe.contentDocument!
		// [CSS RECORD] Adopted sheets live on the document object, not in head/body — wiping
		// innerHTML does not remove them. Reset here or page N-1's adopted styles (and, on a
		// rewind, styles from the future) bleed into this page.
		try {
			( iframeDoc as unknown as { adoptedStyleSheets: CSSStyleSheet[] } ).adoptedStyleSheets = []
		} catch ( e ) {
			// adoptedStyleSheets unsupported/frozen — nothing adopted, nothing to reset
		}
		iframeDoc.body.innerHTML = ''
		iframeDoc.head.innerHTML = ''
		const fragment = iframeDoc.createDocumentFragment()
		const fragUUID = crypto.randomUUID()

		this.registerNode( fragment as unknown as HTMLElement, fragUUID )

		iframeDoc.documentElement.innerHTML = ''
		
		// Only set attributes if this is the HTML tag
		if (
			change.node.tagName &&
			change.node.tagName.toUpperCase() === 'HTML' &&
			change.node.attributes &&
			change.node.UUID === '#html'
		) {
			Object.entries(change.node.attributes).forEach(([key, value]) => {
				try {
					iframeDoc.documentElement.setAttribute(key, value as string)
				} catch (e) {
					console.error('Error setting HTML attribute:', e)
				}
			})
		}
		const callbacks: (() => void)[] = []

		this.applyAddNodes( {
			seq: change.seq,
			time: change.time,
			type: 'ADD_NODES',
			children: change.node.childNodes.map( ( child ) => {
				return {
					...child,
					parentUUID: fragUUID,
				}
			} ),
			parentUUID: fragUUID,
			prevUUID: null,
			nextUUID: null,
		
		}, callbacks )

		callbacks.forEach( ( cb ) => {
			cb()
		} )

		/**
		 * iterate over fragment children and merge with iframe document head and body
		 */

		const childNodes = Array.from( fragment.childNodes )

		childNodes.forEach( ( child ) => {
			const prevSibling = child.previousSibling

			/**
			 * for head and body, we need to merge the children
			 * @note using innerHTML will break text nodes, where some text nodes will be merged into one
			 * so we will need to get the children and append them to a fragment
			 */
			if ( child.nodeName === 'HEAD' ) {
				iframeDoc.head.innerHTML = ''
				const fragment = iframeDoc.createDocumentFragment()
				const appendNodes = Array.from( child.childNodes )
				appendNodes.forEach( ( child ) => {
					fragment.appendChild( child )
				} )
				iframeDoc.head.appendChild( fragment )
				return
			}
			if ( child.nodeName === 'BODY' ) {
				iframeDoc.body.innerHTML = ''
				const fragment = iframeDoc.createDocumentFragment()
				const appendNodes = Array.from( child.childNodes )
				// apply attributes to the body
				Array.from( ( child as HTMLBodyElement ).attributes )
					.forEach( ( attr ) => {
						iframeDoc.body.setAttribute( attr.name, attr.value )
					} )
				appendNodes.forEach( ( child ) => {
					fragment.appendChild( child )
				} )
				iframeDoc.body.appendChild( fragment )
				return
			}

			if ( prevSibling ) {
				prevSibling.after( child )
			}
		} )

		this.mouseElem = this.makeMouse()
		this.trailCanvasCtx = this.canvas.getContext( '2d' )!

		this.__lastUrl = change.url

		this.applyScrollChange( {
			seq: change.seq,
			time: change.time,
			type: 'SCROLL',
			target: '#document',
			scrollTop: change.topScroll || 0,
			scrollLeft: change.leftScroll || 0,
		} )

		triggerEvent( this.__domElement, 'urlchange', {
			url: change.url,
		} )

	}

