const lerp = (start, end, amt) => (1 - amt) * start + amt * end;

const RenderGestureOnTimeline = memo( ( { gest, duration, noCodeEventsFeatureFlag, handleGestureOnTimelineClick } ) => {
  const {
    isRage,
    name,
    time,
    properties,
    params
  } = gest;
  const { isEvent, isSmartEvent, isScreenEvent } = getActionType(gest);

    const icon = () => {
      if (name === 'UI Freeze') return (
        <img alt="Unresponsive" src="/static/sessions/timeline/unresponsive.svg" />
      );
      if (isRage) return (
        <img alt="Rage tap" src="/static/sessions/timeline/rageTap.svg" />
      );
      if (isEvent) return (
        <img alt="Coded event" src="/static/sessions/timeline/coded.svg" />
      );
      if (isSmartEvent) return (
        <StyledGestureImg alt="Nocode event" src="/static/sessions/timeline/smartevent.svg" />
      );
      if (isScreenEvent) return (
        <StyledGestureImg alt="Nocode event" src="/static/sessions/timeline/smartevent.svg" /> 
      );
      return null;
    };

    const tooltipTitle = () => {
      if (name === 'UI Freeze') return 'UI Freeze';
      if (isRage) return 'Rage tap';
      if (isEvent || isSmartEvent || isScreenEvent) return name;
      return null;
    };

  const type = () => {
    if(name === 'UI Freeze') return 'UIFreeze'
    if(isRage) return `rageTap`
    if(isEvent) return `coded_event`
    if(isSmartEvent) return `smart_event`
    if(isScreenEvent) return `screen_event`
    return null
  }

    if (time === undefined) return null;
    const idString = properties?.idString || params?.idString

    const key = `${time}${idString}`;
    const position = (time / duration) * 100;

  return (
    <Tooltip title={ tooltipTitle } placement="top" overlayClassName='gesture-tooltip'>
      <GestureOnTimeline
        key={key}
        style={ {
          left: `calc( ${position}% - 1px)`,
        } }
        left={position} noCodeFlag={ noCodeEventsFeatureFlag } onClick={(e) => handleGestureOnTimelineClick(e, time, type())}>
        { icon() }
      </GestureOnTimeline>
    </Tooltip>
  )
} )

const TimelineActivity = memo(
  ({
    onScreenHover,
    width,
    activityName,
    disabled,
    background,
    onScreenOut,
  }) => {
    const handleMouseOver = React.useCallback(() => {
      onScreenHover(activityName, background);
    }, [onScreenHover, background, onScreenHover]);

    return (
      <ActivityTimelineFill
        aria-disabled={disabled}
        background={background}
        width={width}
        style={ {
          width: `${width}%`,
          background,
        } }
        onMouseOver={handleMouseOver}
        onMouseOut={onScreenOut}
      />
    );
  }
);

const VideoTimeline = ({
  screens,
  activityColorMap,
  selectedScreensMap,
  onScreenHover,
  onScreenOut,
  videoRef,
  sessionId,
}) => {
  const { sessionDetail, rewind } = useSessionTimeLine();
  const { urlReducer: urlQuery } = useSelector(state => state);
  const { parentType } = urlQuery;
  const platform = sessionDetail?.device?.platform;
  const appId = sessionDetail?.appId;
  const isIOS = platform === 2
  const sdkPluginType = sessionDetail?.device?.sdkPluginType;
  const isFlutterWebReplay = platform === 3 && sdkPluginType === 'flutter';
  const {
    data: recordingData,
  } = useFetchAppSetting(['appSetting', appId], parentType === 'shareSession' ? '' : appId);
  const { getScreenLayoutData } = useScreenLayoutContext()
  const nativeIOSReplay = recordingData?.nativeScreenCapture || sessionDetail?.isNativeScreenCaptureEnabled || false;
  const showSchematicReplay = useMemo(() => isIOS && !nativeIOSReplay && schematicFrameworks?.includes(sdkPluginType?.toLowerCase()), [isIOS, nativeIOSReplay, sdkPluginType])

  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext();

  const gestureActivities = React.useMemo(() => {
    const actions = [];
    const data = sessionDetail?.screenTimeline?.activities;

    if (data?.length && screens) {
      data.forEach((el) => {
        el.actions.forEach((action) => {
          const { isEvent, isSmartEvent, isScreenEvent } = getActionType(action);
          if (
            action?.name === 'UI Freeze' ||
            action?.isRage ||
            isEvent ||
            (noCodeEventsFeatureFlag && isSmartEvent) ||
            (noCodeEventsFeatureFlag && isScreenEvent)
          ) {
            actions.push(action);
          }
        });
      });
    }

    return actions;
  }, [sessionDetail, screens, noCodeEventsFeatureFlag]);

  const duration = useMemo(
    () => (screens.length ? screens[screens.length - 1].endTime : 0),
    [screens]
  );

  const activitySegments = useMemo(
    () =>
      screens.reduce((acc, { actions }) => {
        actions.forEach(({ time }) =>
          acc.push((time / duration) * 100)
        );
        // events.forEach(({ time }) => acc.push((time / duration) * 100));
        return acc;
      }, []),
    [screens, duration]
  );

const renderActivities = useMemo(() => {
    return screens.map(({ endTime, time, activityName }, index) => {
        const viewtime = endTime - time;
        const width = (viewtime / duration) * 100;
        const background = getScreenLayoutData(parentType).isSequentialTimelineColor
            ? activityColorMap[index]
            : activityColorMap[activityName];

        return {
            width,
            background,
            activityName,
        };
    });
}, [getScreenLayoutData, screens, duration, activityColorMap, parentType]);

  const rangeRef = useRef();
  const fillRef = useRef();
  const sliderThumbRef = useRef();

  const rangeChangeTimeout = useRef();
  const [desiredTime, setDesiredTime] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);

  useEffect(() => {
    const animate = () => {
      setCurrentTime((prevTime) => lerp(prevTime, desiredTime, 0.1));
      rangeChangeTimeout.current = requestAnimationFrame(animate, 1000/60);
    };

    rangeChangeTimeout.current = requestAnimationFrame(animate, 1000/60);

    return () => {
      if (rangeChangeTimeout.current) {
        cancelAnimationFrame(rangeChangeTimeout.current);
      }
    };
  }, [desiredTime]);

  useEffect(() => {
    const video = videoRef.current;
    if (video && Number.isFinite(currentTime)) {
      video.currentTime = currentTime;
    }
  }, [currentTime]);

  const handleRangeChange = useCallback(
    (e) => {
      const { value } = e.currentTarget;
      const video = videoRef.current;
      if (!video) {
        return;
      }
      const { duration: videoDuration } = video;
      // For Flutter, seekbar progress is measured against session duration
      // so the desired time must be scaled by session duration as well.
      const scaleDuration = isFlutterWebReplay && duration > 0 ? duration : videoDuration;
      const ratio = Math.min(Math.max(parseFloat(value), 0), 1);
      const newTime = ratio * scaleDuration;

      if (!Number.isFinite(newTime)) {
        return;
      }

      setDesiredTime(newTime);

      // debounce
      if (rangeChangeTimeout.current) {
        cancelAnimationFrame(rangeChangeTimeout.current);
      }
      rangeChangeTimeout.current = requestAnimationFrame(() => {
        video.currentTime = newTime;
      }, 1000/60);
    },
    [videoRef, isFlutterWebReplay, duration]
  );

  // will update the range slider
  const handleTimeUpdate = useCallback((e) => {
    const { duration: videoDuration, currentTime: time } = e.currentTarget;
    // For Flutter web replay, session timeline (screens) and raw video file
    // have different durations. Scale video time into session time so that
    // playback progress aligns with screen annotations. When the video ends
    // before the session duration, snap to 100% so the seekbar completes.
    let progress;
    if (isFlutterWebReplay && duration > 0 && videoDuration > 0) {
      const atEnd = videoDuration - time < 0.25;
      progress = atEnd ? 1 : Math.min(time / duration, 1);
    } else {
      progress = videoDuration > 0 ? Math.min(time / videoDuration, 1) : 0;
    }

    // eslint-disable-next-line no-shadow
    const range = rangeRef.current;
    const fill = fillRef.current;
    const sliderThumb = sliderThumbRef.current;

    if (range) {
      // prevent recursion
      range.removeEventListener('change', handleRangeChange);
      // update slider position
      range.value = progress;
      range.addEventListener('change', handleRangeChange);
    }

    if (fill) {
      fill.style.width = `${progress * 100}%`;
    }

    if (sliderThumb) {
      sliderThumb.style.left = `calc(${(progress * 100)}% - 8px)`;
    }
  }, [isFlutterWebReplay, duration]);

  const dispatch = useDispatch();

  useEffect(() => {
    if ( !videoRef ) return undefined
    const video = videoRef.current;

    if (video) {
      video.addEventListener('timeupdate', handleTimeUpdate);
      return () => {
        video.removeEventListener('timeupdate', handleTimeUpdate);
      };
    }
    return undefined;
  }, [videoRef, handleTimeUpdate]);

  // rewind video on timeline click
  const handleTimelineClick = useCallback((e) => {
    const timelineElem = e.currentTarget;
    const video = videoRef.current;

    if(e.target.innerText === 'Schematic replay on') return;

    if (!video) {
      return;
    }
    const { left, width } = timelineElem.getBoundingClientRect();
    const { duration: videoDuration } = video;

    const progress = Math.min(Math.max((e.clientX - left) / width, 0), 1);
    const scaleDuration = isFlutterWebReplay && duration > 0 ? duration : videoDuration;
    const newTime = toVideoTime(progress * scaleDuration);

    if (Number.isFinite(newTime)) {
      video.currentTime = newTime;
    }
  }, [isFlutterWebReplay, duration, videoRef]);

  const playingRef = useRef(false);

  // resume playing on range move end
  const handleMouseUp = React.useCallback(() => {
    const video = videoRef.current;

    if (!video) {
      return;
    }

    if (playingRef.current) {
      const { currentTime: time, duration: videoDuration } = video;
      if (time < videoDuration) {
        video.play().catch( () => null );
      }
    }
    playingRef.current = false;
  }, [videoRef]);

  // pause video on range move
  const handleMouseDown = React.useCallback(() => {
    const video = videoRef.current;

    if (!video) {
      return;
    }
    playingRef.current = !video.paused;
    video.pause();
  }, [videoRef]);

  // attach event listener on mouse enter
  const handleMouseEnter = React.useCallback(() => {
    const range = rangeRef.current;
    if (range) {
      range.addEventListener('input', handleRangeChange);
    }
  }, [handleRangeChange]);

  // remove event listener on mouse leave
  const handleMouseLeave = React.useCallback(() => {
    const range = rangeRef.current;
    if (range) {
      range.removeEventListener('input', handleRangeChange);
    }
  }, [handleRangeChange]);

  const handleGestureOnTimelineClick = React.useCallback(
    (e, time, type) => {
      e.stopPropagation();
      rewind(time);

      dispatch(
        trackPageViews(null, {
          eventName: 'click_on_timeline_marker',
          track_type: 'event',
          eventProperty: {
            sessionId,
            typeOfEvent: type,
          },
        })
      );
    },
    [rewind, dispatch, sessionId]
  );

  const renderGestureOnTimeline = React.useCallback(
    (gest) => {
      const {
        isRage,
        name,
        time,
        properties,
        params
      } = gest;
      const { isEvent, isSmartEvent } = getActionType(gest);

      const icon = () => {
        if (name === 'UI Freeze') return (
          <img alt="Unresponsive" src="/static/sessions/timeline/unresponsive.svg" />
        );
        if (isRage) return (
          <img alt="Rage tap" src="/static/sessions/timeline/rageTap.svg" />
        );
        if (isEvent) return (
          <img alt="Coded event" src="/static/sessions/timeline/coded.svg" />
        );
        if (isSmartEvent) return (
          <img alt="Nocode event" src="/static/sessions/timeline/nocode.svg" />
        );
        return null;
      };

      const tooltipTitle = () => {
        if (name === 'UI Freeze') return 'UI Freeze';
        if (isRage) return 'Rage tap';
        if (isEvent || isSmartEvent) return name;
        return null;
      };

    const type = () => {
      if(name === 'UI Freeze') return 'UIFreeze'
      if(isRage) return `rageTap`
      if(isEvent) return `coded_event`
      if(isSmartEvent) return `smart_event`
      return null
    }

      if (!icon || !time) return null;
      const idString = properties?.idString || params?.idString

      const key = `${time}${idString}`;
      const position = (time / duration) * 100;

    return (
      <Tooltip title={ tooltipTitle } placement="top" overlayClassName='gesture-tooltip'>
        <GestureOnTimeline key={key} left={position} noCodeFlag={ noCodeEventsFeatureFlag } onClick={(e) => handleGestureOnTimelineClick(e, time, type())}>
          { icon() }
        </GestureOnTimeline>
      </Tooltip>
    )
  }, [handleGestureOnTimelineClick, duration, noCodeEventsFeatureFlag])

  // cleanup
  React.useEffect(() => {
    const range = rangeRef.current;
    if (range) {
      return () => {
        range.removeEventListener('input', handleRangeChange);
      };
    }
    return undefined;
  }, [handleRangeChange]);

  const {setOpenModal, CustomPropertyModal} = useCustomPropModal();

  const openIOSReplayModal = useCallback(() => {
    setOpenModal(true);
  }, [setOpenModal])

  const SchematicReplayTag = useMemo(() => (
    <SchematicReplayTagContainer style={{
      bottom: gestureActivities?.length ? '34px' : '14px'
    }} onClick={openIOSReplayModal}>
      Schematic replay on
    </SchematicReplayTagContainer>
  ), [gestureActivities?.length, openIOSReplayModal])


  return (
    <>
      <GlobalStyle />
      <Container>
        <CustomPropertyModal
          title={SchematicReplayModalConst.title}
          subtitle={SchematicReplayModalConst.subtitle}
          hideButtons
          containerClassName="schematic-replay-modal"
        >
          <SchematicIntercomText>
              To enable native screen recording, <Button type='link' onClick={() => showIntercom()}>please reach out to us.</Button>
          </SchematicIntercomText>
          <div className="modal-footer">
            <Button type="link">
              <a
                href={SchematicReplayModalConst.link}
                target="_blank"
                rel="noopener noreferrer"
              >
                Learn more
              </a>
            </Button>
            <Button type="primary" onClick={() => setOpenModal(false)}>
              Got it
            </Button>
          </div>
        </CustomPropertyModal>
        <AcivityTimelineContainer onClick={handleTimelineClick}>
          {renderActivities.map(({ width, background, activityName }, i) => (
            <TimelineActivity
              // eslint-disable-next-line react/no-array-index-key
              key={i}
              width={width}
              disabled={!selectedScreensMap[activityName]}
              activityName={activityName}
              background={background}
              onScreenHover={onScreenHover}
              onScreenOut={onScreenOut}
            />
          ))}
          {activitySegments.map((time, key) => (
            // eslint-disable-next-line react/no-array-index-key
            <ActivitySegment className='test here' key={key} left={time} />
          ))}
          {showSchematicReplay && SchematicReplayTag}
          {
            gestureActivities?.map((action, index) =>
              <RenderGestureOnTimeline
                // eslint-disable-next-line react/no-array-index-key
                key={ index }
                gest={action}
                duration={duration}
                noCodeEventsFeatureFlag={noCodeEventsFeatureFlag}
                handleGestureOnTimelineClick={handleGestureOnTimelineClick}
              />
            )}
        </AcivityTimelineContainer>
        <ProgressContainer>
          <Slider
            id="timeline-slider"
            ref={rangeRef}
            type="range"
            min="0"
            max="1"
            // step="0.0001"
            step={duration > 0 ? 1 / duration : 0.0001}
            defaultValue="0"
            onMouseDown={handleMouseDown}
            onMouseUp={handleMouseUp}
            onMouseEnter={handleMouseEnter}
            onMouseLeave={handleMouseLeave}
            onChange={handleRangeChange}
          />
          <Fill ref={fillRef} />
          <SliderCustom ref={sliderThumbRef} />
        </ProgressContainer>
      </Container>
    </>
  );
};

export default React.memo(VideoTimeline);
