import React from 'react';
import { Dropdown, Switch } from 'antd';
import styled from 'styled-components';
import { useDispatch } from 'react-redux';
import { trackPageViews } from 'redux/actions/trackingReport';
import { useSessionVideoSettings } from 'components/shared/Sessions/Context';

import SettingsIcon from 'public/static/session-replay/settings.svg';

const MenuBtn = styled.button`
  display: ${(props) => (props.isShareSession ? 'none' : 'flex')};
  width: 100%;
  padding: 0;
  background: transparent;
  font-size: inherit;
  border: none;
  text-align: left;
  align-items: center;
  .uc-video-menu-label {
    padding: 8px 10px;
    width: 120px;
  }
  .uc-video-menu-content {
    width: 48px;
  }
  &:hover {
    background: #f5f5f5;
    cursor: pointer;
  }
`;

const CogIcon = styled.span`
  cursor: pointer;
  background-color: #f3f4f5;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;

  &:hover {
    background-color: #f7faff;
  }

  svg {
    color: #090F19;
  }
`;

const SettingMenuContainer = styled.ul`
  background: #fff;
  box-shadow: 0px 0px 18px rgba(0, 0, 0, 0.32);
  border-radius: 6px;
  overflow: hidden;

  button {
    font-size: 12px;
  }
`;

const SettingsMenu = React.memo(
  ({
    parentType,
    isShareSession,
    showTimelineGestures,
    session,
    videoDuration,
  }) => {
    const { playAll, setPlayAll, skipInactivity, setSkipInactivity } =
      useSessionVideoSettings();

    const dispatch = useDispatch();

    const togglePlayAll = React.useCallback(() => {
      setPlayAll((oldValue) => !oldValue);
    }, [setPlayAll]);

    const toggleSkipInactivity = React.useCallback(() => {
      setSkipInactivity((oldValue) => !oldValue);
      const { _id: sessionId } = session || {};

      dispatch(
        trackPageViews(null, {
          eventName: 'skip_inactivity',
          track_type: 'event',
          eventProperty: {
            showTimelineGesturesFlag: false,
            sessionId,
            totalSessionLength: videoDuration,
          },
        })
      );
    }, [setSkipInactivity, dispatch, session, videoDuration]);

    return (
      <SettingMenuContainer className="uc-video-menu-wrap vjs-custom-setting-menu">
        {!showTimelineGestures && (
          <li>
            <MenuBtn type="button" data-intercom-target="Skip inactivity">
              <div className="uc-video-menu-label">Skip Inactivity</div>
              <div className="uc-video-menu-content">
                <Switch
                  size="small"
                  checked={skipInactivity}
                  onChange={toggleSkipInactivity}
                />
              </div>
            </MenuBtn>
          </li>
        )}
        {parentType !== 'heatmapsList' && (
          <li>
            <MenuBtn type="button" isShareSession={isShareSession}>
              <div className="uc-video-menu-label">Play All</div>
              <div className="uc-video-menu-content">
                <Switch
                  size="small"
                  checked={playAll}
                  onChange={togglePlayAll}
                />
              </div>
            </MenuBtn>
          </li>
        )}
      </SettingMenuContainer>
    );
  }
);

const VideoSettings = ({
  isShareSession,
  containerRef,
  parentType,
  showTimelineGestures,
  session,
  videoDuration,
}) => {
  const [visible, setVisible] = React.useState(false);
  const [view, setView] = React.useState('main');

  const handleClose = React.useCallback((newVisibility) => {
    setVisible(newVisibility);
    if (!newVisibility) {
      setView('main');
    }
  }, []);

  const dropDownMenu = React.useMemo(
    () => (
      <SettingsMenu
        parentType={parentType}
        isShareSession={isShareSession}
        showTimelineGestures={showTimelineGestures}
        session={session}
        videoDuration={videoDuration}
      />
    ),
    [view, showTimelineGestures, session, videoDuration]
  );

  const handleGetContainer = React.useCallback(
    () => containerRef.current,
    [containerRef]
  );

  return (
    <Dropdown
      getPopupContainer={handleGetContainer}
      overlay={dropDownMenu}
      trigger="click"
      visible={visible}
      onVisibleChange={handleClose}
      placement="topRight"
    >
      <CogIcon>
        <SettingsIcon />
      </CogIcon>
    </Dropdown>
  );
};

export default React.memo(VideoSettings);
