// since screens are ordered by time, we can use a binary search instead
const findScreenByTime = (screens, findTime, enabledMap) => {
  let start = 0;
  let end = screens.length - 1;
  // Iterate while start not meets end
  while (start <= end) {
    // Find the mid index
    const mid = Math.floor((start + end) / 2);

    // If element is present at mid, return True
    const midScreen = screens[mid];
    const { time, endTime, activityName } = screens[mid];
    // in case no enabledMap provided ignore enabled check
    const enabled = !enabledMap || enabledMap[activityName];
    const found = enabled && findTime >= time && findTime <= endTime;
    if (found) {
      const prevScreen = screens[mid - 1];
      const prevEnabled = !enabledMap || enabledMap[prevScreen?.activityName];
      if (
        prevScreen &&
        prevEnabled &&
        findTime >= prevScreen.time &&
        findTime <= prevScreen.endTime
      ) {
        return prevScreen;
      }
      return midScreen;
    }

    const { endTime: nextMidEndTime } = screens[mid];

    // Else look in left or right half accordingly
    if (nextMidEndTime < findTime) start = mid + 1;
    else end = mid - 1;
  }

  return undefined;
};

// Its for specific case for screen visit to find specific screen due to time inconsistency in the server response
const findScreenVisitByTime = ( screens, findTime, selectedScreenName, screenName ) => {
  for ( let i = 0; i < screens.length - 1; i+=1 ) {
    const screen = screens[ i ]
    const nextScreen = screens[ i + 1 ]

    if ( findTime >= screen.time && findTime <= nextScreen?.time ) {
      if ( !selectedScreenName ) {
        if ( screen.activityName === screenName ) return screen
        if ( nextScreen.activityName === screenName ) return nextScreen
      } else {
        if ( nextScreen.activityName === selectedScreenName ) return nextScreen
        return screen
      }
    }
  }
  return undefined
}

const VideoControls = ({
  appId,
  videoRef,
  toggleFullScreen,
  session,
  screens,
  selectedScreensMap,
  activityColorMap,
  isShareSession,
  skippedLabelRef,
  excludedScreenList,
  multiScreenSkippedData,
  skippedLabelStyleRef,
}) => {
  const dispatch = useDispatch();
  const selectedScreensMapRef = useRef(selectedScreensMap);
    const { getScreenLayoutData } = useScreenLayoutContext();
  const excludedScreenListRef = useRef([]);
  const multiScreenSkippedDataRef = useRef({});
  const scheduleScreen = createRef();
  const timeOutRef = createRef();
  const {
    screenRenamedList,
    urlReducer: { parentType, screenname },
  } = useSelector((state) => state);

  const isWebHeatmaps = useMemo(() => parentType === 'webHeatmaps', [parentType]);
  const isHeatmaps = useMemo(() => parentType === 'heatmapsList', [parentType]);

  const isFlutterWebReplay = useMemo(
    () => session?.device?.platform === 3 && session?.device?.sdkPluginType === 'flutter',
    [session?.device?.platform, session?.device?.sdkPluginType]
  );
  const sessionDuration = useMemo(
    () => (screens?.length ? screens[screens.length - 1].endTime : 0),
    [screens]
  );
  
  const { skipInactivity, setSkipInactivity } = useSessionVideoSettings();
  const { trackUserTimeEvent} = useSessionTableHelper({expanded: true})
  useEffect(() => {
    selectedScreensMapRef.current = selectedScreensMap;
  }, [selectedScreensMap]);

  useEffect(() => {
    excludedScreenListRef.current = excludedScreenList;
  }, [excludedScreenList]);

  useEffect(() => {
    multiScreenSkippedDataRef.current = multiScreenSkippedData;
  }, [multiScreenSkippedData?.seqArrayIndexList]);

  const timeDisplayRef = useRef();
  const durationDisplayRef = useRef();
  const activityDisplayRef = useRef();
  const currentScreenRef = useRef();

  const getActivityColor = useCallback((activityName, activityIndex) => {
    if (getScreenLayoutData(parentType).isSequentialTimelineColor) {
        return timeLineSequentialColor(activityIndex)
    }
    return activityColorMap[activityName]
  } , [activityColorMap, getScreenLayoutData, parentType]);

  const resetVideo = useCallback(() => {
    const displayTime = timeDisplayRef.current;
    const displayActivity = activityDisplayRef.current;

    if (displayTime) {
      displayTime.innerText = '0:00';
    }
    if (displayActivity) {
      displayActivity.innerText = '';
    }
  }, []);

  useEffect(() => {
    resetVideo();
  }, [session?.screenVideo]);

  const {
    setPlaying,
    nextSessionCallbackRef,
    prevSessionCallbackRef,
    playbackRateRef,
    playAllRef,
    timeRef,
    setCurrentScreen,
  } = useSessionVideoControlls();

  const { selectedTab, setSelectedTab, setNoteTime, setSelectedScreenName, selectedScreenName } = useSessionSidebar();
  const { setVideoLimitPopup } = useSessionTimeLine();
  const { setUserPausedVideo } = useSessionVideoContext();

  const toggleBtnRef = useRef();

  const updateToggleBtn = useCallback((newState) => {
    const toggleBtn = toggleBtnRef.current;
    if (toggleBtn) {
      toggleBtn.setAttribute('aria-label', newState);
    }
  }, []);

  const hoverActivityDisplayRef = useRef();

  const handleActivityHover = useCallback((activityName, color) => {
    const displayActivity = hoverActivityDisplayRef.current;
    if (displayActivity) {
      displayActivity.innerText = activityName;
      displayActivity.style.color = color;
    }
  }, []);

  const handleActivityOut = useCallback(() => {
    const displayActivity = hoverActivityDisplayRef.current;
    if (displayActivity) {
      displayActivity.innerText = '';
    }
  }, []);

  const isNextDisabled = !nextSessionCallbackRef.current || typeof nextSessionCallbackRef.current !== 'function';
  const isPrevDisabled = !prevSessionCallbackRef.current || typeof prevSessionCallbackRef.current !== 'function';

  const handleNextSession = useCallback(() => {
    const callback = nextSessionCallbackRef.current;
    if (callback && typeof callback === 'function') {
      callback();
    }
  }, [nextSessionCallbackRef]);

  const handlePrevSession = useCallback(() => {
    const callback = prevSessionCallbackRef.current;
    if (callback && typeof callback === 'function') {
      callback();
    }
  }, [prevSessionCallbackRef]);

  useEffect(() => {
    const videoElem = videoRef.current;
    const displayActivity = activityDisplayRef.current;

    if (videoElem) {
      const handlePlay = () => {
        setPlaying(true);
        updateToggleBtn('pause');
      };
      const handlePause = () => {
        setPlaying(false);
        updateToggleBtn('play');
        trackUserTimeEvent(session?.id, timeRef?.current);
      };

      const handleEnded = () => {
        const playAll = playAllRef.current;
        const playNextCallback = nextSessionCallbackRef.current;
        if (playAll && playNextCallback) {
          playNextCallback();
          return;
        }
        setPlaying(false);
        updateToggleBtn('replay');
      };

      const getDisplayDuration = () => {
        const { duration: videoDuration } = videoElem;
        if (isFlutterWebReplay && sessionDuration > 0 && sessionDuration < videoDuration) {
          return sessionDuration;
        }
        return videoDuration;
      };

      const handleMetaLoaded = () => {
        if (durationDisplayRef.current) {
          durationDisplayRef.current.innerText = formatTime(getDisplayDuration());
        }
      };

      const handleTimeUpdate = () => {
        const displayTime = timeDisplayRef.current;
        const { currentTime } = videoElem;
        const displayDuration = getDisplayDuration();
        const clampedTime = Number.isFinite(displayDuration)
          ? Math.min(currentTime, displayDuration)
          : currentTime;
        if (displayTime) displayTime.innerText = formatTime(clampedTime);
        if (durationDisplayRef.current) {
          durationDisplayRef.current.innerText = formatTime(displayDuration);
        }
      };
      const displayScreenSkipLabel = (screenActivity) => {
        let len;
        const { seqArrayIndexList = [] } = multiScreenSkippedDataRef.current;
        const activityIndex = screens.indexOf(screenActivity);
        const isScreensSkipped =
          seqArrayIndexList
            .reduce((acc, val) => acc.concat(val), [])
            .map((v) => v.screenIndex)
            .indexOf(activityIndex) > -1;
        if (isScreensSkipped) {
          seqArrayIndexList.map((skippedScreens) => {
            if (
              skippedScreens
                .map(({ screenIndex }) => screenIndex)
                .indexOf(activityIndex) > -1
            )
              len = skippedScreens.length;
            return skippedScreens;
          });
          skippedLabelRef.current.innerText = `Skipping ${len} ${
            len > 1 ? 'screens' : 'screen'
          }`;
        } else skippedLabelRef.current.innerText = `Skipping 1 screen`;
        skippedLabelStyleRef.current?.classList?.add('display-label');
      };
      const handleScreenSkip = (screenActivity, nextAvailable) => {
        if (!excludedScreenListRef.current.length) return;
        const { duration } = videoElem;
        if (scheduleScreen.current === nextAvailable) return;
        displayScreenSkipLabel(screenActivity);
        if (timeOutRef.current) {
          clearTimeout(timeOutRef.current);
          timeOutRef.current = null;
        }
        scheduleScreen.current = nextAvailable;
        timeOutRef.current = setTimeout(() => {
          timeOutRef.current = null;
          scheduleScreen.current = null;
          const newTime = nextAvailable
            ? toVideoTime(nextAvailable.time + 0.01)
            : Math.ceil(duration);
          if (Number.isFinite(newTime)) {
            videoElem.currentTime = newTime;
          }
          setCurrentScreen(nextAvailable);
          skippedLabelStyleRef.current?.classList?.remove('display-label');
        }, 1000);
      };

      const handleActivityUpdate = () => {
        const { currentTime, duration } = videoElem;
        const currentScreen = currentScreenRef.current;
        const selectedScreensMapValue = selectedScreensMapRef.current;
        const isCurrentScreen =
          currentScreen &&
          currentScreen.time >= currentTime &&
          currentTime < currentScreen.endTime;

        timeRef.current = currentTime;

        if (currentTime === duration) {
          setCurrentScreen(null);
          return;
        }
        // video time matches the current screen
        if (isCurrentScreen) {
          const isActive = selectedScreensMapValue[currentScreen.activityName];

          // nothing to do
          if (isActive) return;

          // if disabled, rewind to next available screen
          const currentScreenIndex = screens.indexOf(currentScreen);
          const nextAvailable = screens
            .slice(currentScreenIndex + 1) // only next screens
            .find(({ activityName }) => selectedScreensMapValue[activityName]);

          currentScreenRef.current = nextAvailable;
          
          // no next screen found, end the video
          if (!nextAvailable) {
            videoElem.pause();
            const endTime = Math.ceil(duration);
            if (Number.isFinite(endTime)) {
              videoElem.currentTime = endTime;
            }
            return;
          }
          // @todo: fix this
          const { activityName } = nextAvailable;
          // update current screen text
          const renamedScreenName = screenRenamedList[activityName];
          displayActivity.innerText = renamedScreenName || activityName;
          displayActivity.style.color = getActivityColor(activityName, currentScreenIndex);
          const nextTime = toVideoTime(nextAvailable.time);
          if (Number.isFinite(nextTime)) {
            videoElem.currentTime = nextTime;
          }
          currentScreenRef.current = nextAvailable;
          return;
        }

        // find by current time
        const currentTimeScreen = findScreenByTime(screens, currentTime);

        // shouldn't happen
        if (!currentTimeScreen) return;

        const { activityName: currentActivityName } = currentTimeScreen;
        const isActivityEnabled = selectedScreensMapValue[currentActivityName];

        // if disabled find next available
        if (!isActivityEnabled && videoElem) {

          // we do not need to set current screen if it's notes
          if (selectedTab === 'notes') return;

          const currentTimeScreenIndex = screens.indexOf(currentTimeScreen);
          const nextAvailable = screens
            .slice(currentTimeScreenIndex + 1) // only next screens
            .find(({ activityName }) => selectedScreensMapValue[activityName]);

          if (!nextAvailable) {
            videoElem.pause();
            handleScreenSkip(currentTimeScreen, nextAvailable);
            return;
          }
          handleScreenSkip(currentTimeScreen, nextAvailable);
          return;
        }

        currentScreenRef.current = currentTimeScreen;
        setCurrentScreen(currentTimeScreen);
        const renamedScreenName = screenRenamedList[currentActivityName];
        displayActivity.innerText = renamedScreenName || currentActivityName;
        displayActivity.style.color = getActivityColor(currentActivityName, screens.indexOf(currentTimeScreen));
      };

      const handleSeeked = () => {
        const { paused } = videoElem;

        updateToggleBtn(paused ? 'play' : 'pause');
      };

      const handleActivitySeeked = () => {
        const { currentTime, duration } = videoElem;
        if (currentTime === duration) {
          setCurrentScreen(null);
          return;
        }
        const foundScreen =
          isHeatmaps
            ? findScreenVisitByTime(
                screens,
                currentTime,
                selectedScreenName,
                screenname,
              )
            : findScreenByTime(screens, currentTime);
        // shouldn't happen
        if (!foundScreen) return;

        if (!foundScreen) {
          // no available screens found, end the video
          // prevent recursion
          videoElem.removeEventListener('timeupdate', handleTimeUpdate);
          videoElem.pause();
          const endTime = Math.ceil(duration);
          if (Number.isFinite(endTime)) {
            videoElem.currentTime = endTime;
          }
          videoElem.addEventListener('timeupdate', handleTimeUpdate);
          return;
        }

        const { activityName } = foundScreen;
        setCurrentScreen(foundScreen);

        const renamedScreenName = screenRenamedList[activityName];
        displayActivity.innerText = renamedScreenName || activityName;
        displayActivity.style.color = getActivityColor(activityName, screens.indexOf(foundScreen));
        currentScreenRef.current = foundScreen;
      };

      videoElem.addEventListener('play', handlePlay);
      videoElem.addEventListener('pause', handlePause);
      videoElem.addEventListener('ended', handleEnded);

      videoElem.addEventListener('seeked', handleSeeked);
      videoElem.addEventListener('seeked', handleActivitySeeked);
      // trigger activity update on video load
      videoElem.addEventListener('canplaythrough', handleActivitySeeked);

      videoElem.addEventListener('timeupdate', handleTimeUpdate);
      videoElem.addEventListener('timeupdate', handleActivityUpdate);

      videoElem.addEventListener('loadedmetadata', handleMetaLoaded, false);

      return () => {
        videoElem.removeEventListener('play', handlePlay);
        videoElem.removeEventListener('pause', handlePause);
        videoElem.removeEventListener('ended', handleEnded);

        videoElem.removeEventListener('seeked', handleSeeked);
        videoElem.removeEventListener('seeked', handleActivitySeeked);
        videoElem.removeEventListener('canplaythrough', handleActivitySeeked);

        videoElem.removeEventListener('timeupdate', handleTimeUpdate);
        videoElem.removeEventListener('timeupdate', handleActivityUpdate);

        videoElem.removeEventListener('loadedmetadata', handleMetaLoaded, false);
      }
    }
    return undefined;
  }, [videoRef, setCurrentScreen, selectedScreenName, screens, getActivityColor, isFlutterWebReplay, sessionDuration]);

  useEffect( () => {
    setSelectedScreenName( null )
  }, [ setSelectedScreenName ] )

  useEffect(() => {
    const videoElem = videoRef.current;
    if (!videoElem) {
      return () => null;
    }

    let animationFrame;
    const step = () => {
      timeRef.current = videoElem.currentTime;
      animationFrame = requestAnimationFrame(step);
    };

    animationFrame = requestAnimationFrame(step);
    return () => {
      cancelAnimationFrame(animationFrame);
    };
  }, [videoRef, timeRef]);

  const handlePlaybackChange = useCallback(
    (newPlaybackRate) => {
      const videoElem = videoRef.current;
      if (!videoElem) {
        return;
      }
      videoElem.playbackRate = newPlaybackRate;
      playbackRateRef.current = newPlaybackRate;
    },
    [playbackRateRef]
  );

  const { _id: sessionId } = session || {};

  const handleToggle = () => {
    const videoElem = videoRef.current;
    if (
      sessionId &&
      (!session?.isPlayable || session?.verifiedPastVideoRecordingLimit)
    ) {
      setVideoLimitPopup(true);
      return null;
    }
    if (videoElem && session?.isPlayable) {
      if (!videoElem.paused) {
        videoElem.pause();
      } else {
        setUserPausedVideo(false);
        videoElem.play().catch( () => null );
        dispatch(
          fetchPlanHatApi({
            action: `Played video on ${mappedSegmentType[parentType]}`,
          })
        );
      }
    }
    return null;
  };

  const handleNoteIcon = useCallback(() => {
    const videoElem = videoRef.current;
    videoElem && videoElem.pause();
    setNoteTime(timeRef?.current);
    setSelectedTab('notes');
  }, [videoRef]);

  const toggleSkipInactivity = useCallback(() => {
    setSkipInactivity(!skipInactivity);

    dispatch(
      trackPageViews(null, {
        eventName: 'skip_inactivity',
        track_type: 'event',
        eventProperty: {
          showTimelineGesturesFlag: true,
          sessionId,
          totalSessionLength: videoRef.current?.duration,
        },
      })
    );
  }, [setSkipInactivity, skipInactivity, dispatch, sessionId, videoRef]);

  const containerRef = useRef();

  return (
    <Controls ref={containerRef}>
      <Timeline>
        <VideoTimeline
          selectedScreensMap={selectedScreensMap}
          activityColorMap={activityColorMap}
          screens={screens}
          onScreenHover={handleActivityHover}
          onScreenOut={handleActivityOut}
          videoRef={videoRef}
          sessionId={sessionId}
        />
      </Timeline>
      <Actions>
        <ActionsLeft>
          <span className="button-grp">
            {!getScreenLayoutData(parentType).isNewVideoControls && <NavBtn
              isShareSession={isShareSession}
              onClick={handlePrevSession}
              disabled={isPrevDisabled}
              type="button"
            >
              <i
                className="vjs-icon-previous-item"
                data-intercom-target="Video Prev"
              >
                <PrevIcon />
              </i>
            </NavBtn>}
            <PlayPauseBtn
              ref={toggleBtnRef}
              isShareSession={isShareSession}
              aria-label="play"
              type="button"
              onClick={() => handleToggle()}
            >
              <i className="vjs-icon-play" data-intercom-target="Video Play">
                <PlayIcon />
              </i>
              <i className="vjs-icon-pause" data-intercom-target="Video Pause">
                <PauseIcon />
              </i>
              <i
                className="vjs-icon-replay"
                data-intercom-target="Video Replay"
              >
                <ReplayIcon />
              </i>
            </PlayPauseBtn>
             {!getScreenLayoutData(parentType).isNewVideoControls && <NavBtn
              isShareSession={isShareSession}
              onClick={handleNextSession}
              disabled={isNextDisabled}
              type="button"
            >
              <i
                className="vjs-icon-next-item"
                data-intercom-target="Video Next"
              >
                <NextIcon />
              </i>
            </NavBtn>}
          </span>
          <span>
            <span ref={timeDisplayRef}>0:00</span>/
            <span ref={durationDisplayRef}>0:00</span>
          </span>
          <ActivityName ref={hoverActivityDisplayRef} />
          <ActivityName ref={activityDisplayRef} />
        </ActionsLeft>
        <ActionsRight>
        {!isShareSession && getScreenLayoutData(parentType).isNewVideoControls && (
          <AddNotesComponent onClick={handleNoteIcon} newIcon/>
         )}
         <SkipInactivitySwitch toggleSkipInactivity={toggleSkipInactivity} skipInactivity={skipInactivity} />

          <span data-intercom-target="Video Speed">
            <VideoPlaybackControls
              containerRef={containerRef}
              onPlayrateChange={handlePlaybackChange}
            />
          </span>

        {!isShareSession && !getScreenLayoutData(parentType).isNewVideoControls && (
            <AddNotesComponent onClick={handleNoteIcon} />
         )}
          <span data-intercom-target="Video Settings">
            {isHeatmaps || isWebHeatmaps ? null : (
              <VideoSettings
                containerRef={containerRef}
                appId={appId}
                isShareSession={isShareSession}
                parentType={parentType}
                showTimelineGestures
                session={session}
                videoDuration={videoRef?.current?.duration}
              />
            )}
          </span>
          {!(isHeatmaps || isWebHeatmaps) && (
            <FullScreenBtn onClick={toggleFullScreen}>
              <i className="fullscreen-icon" />
            </FullScreenBtn>
          )}
        </ActionsRight>
      </Actions>
    </Controls>
  );
};

export default memo(VideoControls);
