/* eslint-disable no-param-reassign */
/* eslint-disable @typescript-eslint/no-non-null-assertion */
import { IVideoInterface } from '../WebReplay/types';
import { toVideoTime } from '../utils';

export const GestureWrapperClassName = 'gesture-wrapper';

export interface ReplayGesture {
  start: number;
  end: number;
  x: number;
  y: number;
  x2: number;
  y2: number;
  g: number;
  o: number;
}

export interface ReplaySessionData {
  newOverlay: boolean;
  device: {
    deviceWidth: number;
  };
}

interface GestureNode {
  node: Element;
  gesture: ReplayGesture;
  animation: Animation;
  state: 'pending' | 'finished';
}

/**
 * @note for web replay, we don't need the session information
 * will add a fallback for the session information
 */
const SessionFallback: ReplaySessionData = {
  newOverlay: true,
  device: {
    deviceWidth: 375,
  },
}

export default class SessionGestures {
  session: ReplaySessionData | null = null;

  videoElem: HTMLVideoElement | IVideoInterface | null = null;

  wrapper: HTMLElement | null = null;

  gestures: ReplayGesture[] = [];

  animateNodes: GestureNode[] = [];

  scale = 1;

  overlayScaled = false;

  skipInactivity = false;

  metaLoaded = false;

  screens = [];

  isFlutterWeb = false;

  videoResizeFn: (() => void) | null = null;

  private readonly MIN_REPLAY_TIME_BEFORE = 2; // seconds before gesture

  private readonly MIN_REPLAY_TIME_AFTER = 2;  // seconds after gesture

  private readonly MIN_SKIP_DURATION = 3;      // minimum seconds to skip

  constructor({
    gestures,
    container,
    video,
    session,
    skipInactivity,
    videoResizeFn,
    isFlutterWeb = false,
  }: {
    gestures: ReplayGesture[];
    container: HTMLElement;
    video: HTMLVideoElement | IVideoInterface;
    session?: ReplaySessionData;
    skipInactivity: boolean;
    videoResizeFn: (() => void);
    isFlutterWeb?: boolean;
  }) {
    this.wrapper = document.createElement('div');

    container.appendChild(this.wrapper);

    this.session = session || SessionFallback
    this.gestures = gestures;
    this.videoElem = video;
    this.videoResizeFn = videoResizeFn;
    this.isFlutterWeb = isFlutterWeb;


    if ( this.videoElem.readyState >= 2 ) {
      setTimeout( () => {
        this.handleMetaLoaded();
        if ( this.videoResizeFn ) {
          this.videoResizeFn();
        }
        this.handleRewind();
      } )
    }
    this.videoElem.addEventListener('loadedmetadata', this.handleMetaLoaded);
    this.skipInactivity = skipInactivity;
  }

  genScreenTriggerKeyFrame(node: Element, { time }: { time: number }) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const { playbackRate } = this.videoElem!
    const delay = (time * 1000) / playbackRate;

    const frames = [
      {
        fontSize: 1,
      },
      {
        fontSize: 2,
      },
    ];

    const keyframes = new KeyframeEffect(node, frames, {
      duration: 0.0001,
      iterations: 1,
      delay,
      easing: 'linear',
      fill: 'forwards',
    });

    return keyframes;
  }

  genKeyFrame( node: Element, { start, end, x, y, x2, y2, g: ges, o: orient }: ReplayGesture) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const { playbackRate, videoWidth } = this.videoElem!
    const { newOverlay } = this.session!
    const duration = Math.max((end - start) * 1000, 0) / playbackRate;
    const delay = Math.max(
      (start * 1000) / playbackRate - 0.00001 * duration,
      0
    );

    const isInvertedBool = newOverlay && (orient === 0 || orient === 2);
    const isInverted = isInvertedBool as unknown as number
    const isInvertedNeg = !isInvertedBool as unknown as number

    const useX =
      isInverted * (videoWidth - y * this.scale) + isInvertedNeg * x * this.scale;
    const useY = isInverted * x * this.scale + isInvertedNeg * y * this.scale;

    // simple touch
    let frames = [];
    if (ges === 0 || ges === 1 || ges === 9) {
      ( node as HTMLElement ).style.transform = `translate(calc( ${useX}px - 50% ), calc( ${useY}px - 50% ))`
      frames = [
        {
          transform: `translate(calc( ${useX}px - 50% ), calc( ${useY}px - 50% ))`,
          opacity: 0,
          offset: 0.0,
        },
        {
          transform: `translate(calc( ${useX}px - 50% ), calc( ${useY}px - 50% ))`,
          opacity: 1,
          offset: 0.00001,
        },
        {
          transform: `translate(calc( ${useX}px - 50% ), calc( ${useY}px - 50% ))`,
          opacity: 1,
          offset: 0.99999,
        },
        {
          transform: `translate(calc( ${useX}px - 50% ), calc( ${useY}px - 50% ))`,
          opacity: 0,
          offset: 1,
        },
      ];

      // prob. swipe
    } else if (ges === 11 || (ges >= 2 && ges <= 5)) {
      x2 = x2 || 0;
      y2 = y2 || 0;

      const useX2 =
        isInverted * (videoWidth - y2 * this.scale) +
        isInvertedNeg * x2 * this.scale;
      const useY2 =
        isInverted * x2 * this.scale + isInvertedNeg * y2 * this.scale;

      ( node as HTMLElement ).style.transform = `translate(calc( ${useX}px - 50% ), calc( ${useY}px - 50% ))`

      frames = [
        {
          transform: `translate(calc( ${useX}px - 50% ), calc( ${useY}px - 50% ))`,
          opacity: 0,
          offset: 0.0,
        },
        {
          transform: `translate(calc( ${useX}px - 50% ), calc( ${useY}px - 50% ))`,
          opacity: 1,
          offset: 0.00001,
        },
        {
          transform: `translate(calc( ${useX}px - 50% ), calc( ${useY}px - 50% ))`,
          opacity: 1,
        },
        {
          transform: `translate(calc( ${useX2}px - 50% ), calc( ${useY2}px - 50% ))`,
          opacity: 1,
        },
        {
          transform: `translate(calc( ${useX2}px - 50% ), calc( ${useY2}px - 50% ))`,
          opacity: 1,
          offset: 0.99999,
        },
        {
          transform: `translate(calc( ${useX2}px - 50% ), calc( ${useY2}px - 50% ))`,
          opacity: 0,
          offset: 1,
        },
      ];
    } else {
      return undefined;
    }

    const keyframes = new KeyframeEffect(node, frames, {
      duration,
      iterations: 1,
      delay,
      easing: 'linear',
      fill: 'forwards',
    });

    return keyframes;
  }

  attachControls() {
    this.videoElem!.addEventListener('ended', this.handleEnded);
    this.videoElem!.addEventListener('pause', this.handlePause);
    this.videoElem!.addEventListener('play', this.handlePlay);
    this.videoElem!.addEventListener('seeked', this.handleRewind);
    this.videoElem!.addEventListener('ratechange', this.handlePlayRateChange);
  }

  drawAnimationNodes() {
    const fragment = new DocumentFragment();
    const baseNode = document.createElement('div');

    baseNode.style.width = `calc( 32px * var( --video-scale, 1 ) )`;
    baseNode.style.height = `calc( 32px * var( --video-scale, 1 ) )`;
    baseNode.style.background = '#5D97FF';
    baseNode.style.borderRadius = '50%';
    baseNode.style.position = 'absolute';
    baseNode.style.top = '0%';
    baseNode.style.left = '0%';
    baseNode.style.margin = '0';
    baseNode.style.opacity = '0';
    baseNode.style.boxShadow = '-1px 1px 2px 1px #2d32ff';

    this.animateNodes = this.gestures.reduce((acc, gesture) => {
      const node = baseNode.cloneNode();

      fragment.appendChild(node);

      const keyframes = this.genKeyFrame(node as Element, gesture);

      if (!keyframes) {
        return acc;
      }

      const animation = new Animation(keyframes, document.timeline);
      // used to detect when gesture started playing

      animation.pause();

      const gestureNode: GestureNode = {
        node: node as Element,
        gesture,
        animation,
        state: 'pending',
      }

      animation.onfinish = () => {
        gestureNode.state = 'finished';
        if (this.skipInactivity) {
          const { currentTime, duration } = this.videoElem!;
          const currentGestureIndex = this.animateNodes.indexOf(gestureNode);

          // Check if we're within the replay window of the next gesture
          const nextGesture = this.animateNodes[currentGestureIndex + 1];
          if (nextGesture) {
            const { gesture: { start, end } } = nextGesture;
            const gestureStart = Math.max(0, start - this.MIN_REPLAY_TIME_BEFORE);
            const gestureEnd = end + this.MIN_REPLAY_TIME_AFTER;
            
            // If we're not in the replay window and time to next gesture is sufficient
            if (currentTime < gestureStart && (start - currentTime) > this.MIN_SKIP_DURATION) {
              const newTime = toVideoTime(gestureStart);
              if (Number.isFinite(newTime)) {
                this.videoElem!.currentTime = newTime;
              }
            }
          } else {
            // If no next gesture, skip to end
            const newTime = Math.ceil(duration);
            if (Number.isFinite(newTime)) {
              this.videoElem!.currentTime = newTime;
            }
          }
        }
      };

      acc.push(gestureNode);
      return acc;
    }, [] as GestureNode[]);

    this.wrapper!.appendChild(fragment);
  }

  handleMetaLoaded = () => {
    const { videoHeight, videoWidth } = this.videoElem!;
    const {
      device: { deviceWidth },
    } = this.session!;
    // Flutter SDK already records click coords in frame-pixel space,
    // so no device→frame conversion is needed.
    const scale = this.isFlutterWeb ? 1 : (1 / deviceWidth) * videoWidth;

    this.wrapper!.style.width = `${videoWidth}px`;
    this.wrapper!.style.height = `${videoHeight}px`;
    this.wrapper!.style.transformOrigin = `left top`;
    this.wrapper!.style.position = `absolute`;
    this.wrapper!.style.top = `50%`;
    this.wrapper!.style.left = `50%`;
    this.wrapper!.style.transform = `translate(-50%, -50%)`;
    this.wrapper!.classList.add(GestureWrapperClassName);

    this.scale = scale;

    this.drawAnimationNodes();
    this.attachControls();

    this.metaLoaded = true;
  };

  handleEnded = () => {
    this.animateNodes.forEach((node) => {
      const { animation } = node;
      animation.currentTime = 0;
      node.state = 'pending';
    });
  };

  handleRewind = () => {
    const { currentTime, paused } = this.videoElem!;
    const newAnimationTime = currentTime * 1000;

    this.animateNodes
      .filter(({ gesture }) => {
        const { end } = gesture;

        return end >= currentTime;
      })
      .forEach((node) => {
        const { animation, state } = node;
        animation.currentTime = newAnimationTime;
        if (!paused) {
          animation.play();
        } else if (state === 'finished') {
          animation.play();
          animation.pause();
        }
        node.state = 'pending';
      });

    this.animateNodes
      .filter(({ gesture }) => {
        const { end } = gesture;

        return end < currentTime;
      })
      .forEach((node) => {
        const { animation } = node;
        animation.currentTime = newAnimationTime;
        animation.pause();
        node.state = 'finished';
      });
  };

  handlePause = () => {
    this.animateNodes.forEach(({ animation }) => {
      animation.pause();
    });
  };

  handlePlay = () => {
    this.animateNodes.forEach(({ animation, state }) => {
      if (state === 'pending') {
        animation.play();
      }
    });

    if (this.skipInactivity && this.metaLoaded) {
      this.handleSkipInactivity();
    }
  };

  handlePlayRateChange = () => {
    const { playbackRate } = this.videoElem!;
    this.animateNodes.forEach((node) => {
      const { animation } = node;
      animation.playbackRate = playbackRate;
    });
  };

  setSkipInactivity = (newValue: boolean) => {
    this.skipInactivity = newValue;

    const { paused } = this.videoElem!;
    if (!paused && this.metaLoaded) {
      this.handleSkipInactivity();
    }
  };

  handleSkipInactivity = () => {
    const { skipInactivity, metaLoaded } = this;
    if (!skipInactivity && !metaLoaded) {
      return;
    }

    const { currentTime, paused, duration } = this.videoElem!;

    if (paused) {
      return;
    }

    // Find current gesture and its timing
    const currentGesture = this.animateNodes.find(
      ({ gesture: { start, end } }) => {
        const gestureStart = Math.max(0, start - this.MIN_REPLAY_TIME_BEFORE);
        const gestureEnd = end + this.MIN_REPLAY_TIME_AFTER;
        return currentTime >= gestureStart && currentTime <= gestureEnd;
      }
    );

    // If we're within the replay window of a gesture, don't skip
    if (currentGesture) {
      return;
    }

    // Find next gesture
    const nextGesture = this.animateNodes.find(
      ({ gesture: { start } }) => start > currentTime
    );

    if (nextGesture) {
      const { gesture: { start } } = nextGesture;
      const timeToNextGesture = start - currentTime;
      
      // Only skip if the time to next gesture is greater than minimum skip duration
      if (timeToNextGesture > this.MIN_SKIP_DURATION) {
        // Skip to minimum replay time before the next gesture
        const skipToTime = Math.max(0, start - this.MIN_REPLAY_TIME_BEFORE);
        const newTime = Math.max(toVideoTime(skipToTime), currentTime);
        if (Number.isFinite(newTime)) {
          this.videoElem!.currentTime = newTime;
        }
      }
    } else {
      // If no next gesture, skip to end
      const newTime = Math.ceil(duration);
      if (Number.isFinite(newTime)) {
        this.videoElem!.currentTime = newTime;
      }
    }
  };

  destroy() {
    this.videoElem!.removeEventListener('ended', this.handleEnded);
    this.videoElem!.removeEventListener('pause', this.handlePause);
    this.videoElem!.removeEventListener('play', this.handlePlay);
    this.videoElem!.removeEventListener('seeked', this.handleRewind);
    this.videoElem!.removeEventListener('ratechange', this.handlePlayRateChange);
    this.videoElem!.removeEventListener('loadedmetadata', this.handleMetaLoaded);

    this.wrapper!.remove();
  }
}
