const TIMER_DELAY = 1000;

const SessionVideo = ({
  session = {},
  appId,
  toggleFullScreen,
  multiScreenSkippedData,
  blurBackground,
}) => {
  const dispatch = useDispatch();
  const queryClient = useQueryClient();
  const { getScreenLayoutData } = useScreenLayoutContext()
  const { autoPlay } = useSessionAutoPlay();
  const {
    isPlaying: videoPlaying,
    setUserTime,
    userTime,
  } = useSessionVideoContext();

  const {
    setVideoLimitPopup,
    videoLimitPopup,
    rewind,
    sessionQueriesToInvalidate,
    setSessionQueriesToInvalidate,
  } = useSessionTimeLine();
  const { selectedTab, screenNumber } = useSessionSidebar();

  const autoPlayRef = useRef(autoPlay);

  const video = useMemo(() => session.screenVideo, [session]);

  // raw video ref will be passed to the video element
  // or to the web sdk replay component
  const videoRef = useRef();

  const [ videoRefLoaded, setVideoRefLoaded ] = useState( false )

  React.useEffect( () => {
    setVideoRefLoaded( false )
  }, [ session.screenVideo ] )

  React.useEffect( () => {
    // No video means no video element will ever mount, so there is nothing to poll for.
    if ( !session.screenVideo ) return undefined

    let timeout = null;
    const doCheck = () => {
      if ( videoRef.current ) {
        setVideoRefLoaded( true )
        return
      }
      timeout = setTimeout( doCheck, 100 )
    }

    doCheck()
    return () => clearTimeout( timeout )
  }, [ session.screenVideo ] )

  const { sessionDetail, sessionLogs } = useSessionTimeLine();
  const isSessDataLoaded = useMemo(() => !!sessionDetail, [sessionDetail]);

  const containerRef = useRef();
  const contentRef = useRef();
  const scalledContainerRef = useRef();
  const videoContainerRef = useRef();
  const currentScreenRef = useRef();
  const videoGestures = useRef();
  const skippedLabelStyleRef = useRef();
  const skippedLabel = React.useRef();
  const [videoState, setVideoState] = useState('pending');
  const prevSessionIdRef = useRef();
  const initdoneRef = useRef(false);

  const { isAppLogEnabled, isPlayable } = sessionDetail || {};

  const isWebSDK = useMemo(
    () => sessionDetail?.device?.platform === 3,
    [sessionDetail]
  );

  const isFlutterWeb = useMemo(
    () => isWebSDK && sessionDetail?.device?.sdkPluginType === 'flutter',
    [sessionDetail, isWebSDK]
  );

  const flutterUrlTimeline = useMemo(() => {
    if (!isFlutterWeb) return null;
    const activities = session?.screenTimeline?.activities || [];
    const entries = [];
    activities.forEach((activity) => {
      (activity.actions || []).forEach((action) => {
        if (action.name !== 'uxc_url_navigate') return;
        const params = action.params || {};
        let {url} = params;
        if (!url && params.hostname) {
          const scheme = params.hostname.startsWith('localhost') ? 'http://' : 'https://';
          const path = params.path || '';
          const query = params.query ? `?${params.query}` : '';
          const hash = params.hash ? `#${params.hash}` : '';
          url = `${scheme}${params.hostname}${path}${query}${hash}`;
        }
        if (!url) return;
        entries.push({ time: action.time ?? 0, url });
      });
    });
    return entries.length ? entries : null;
  }, [isFlutterWeb, session]);

  const showWebReplayUrl = isWebSDK || !!flutterUrlTimeline;

  const {
    urlReducer: urlQuery,
    currentOrgReducer: { planType },
    screenTimelineReducer: {
      selectedScreens = [],
      skipDeselectedToggle,
      isLastSelectedScreen,
      screenList,
    },
    appFilter: {
      session: { segment: sessionSegment },
    },
  } = useSelector((state) => state);

  const { sessionid, parentType, starttime, screenname } = urlQuery;

  const defaultStartTime = React.useMemo(
    () =>
      parentType === 'heatmapsList'
        ? session?.screenTimeline?.activities[screenNumber]?.time
        : starttime,
    [parentType, screenNumber, session.screenTimeline.activities, starttime]
  );

  const screens = React.useMemo(
    () => session.screenTimeline.activities,
    [session]
  );

  // const selectedScreensPerToggle = useMemo(
  //   () =>  session.screenTimeline.activities.map( ( { activityName } ) => activityName ),
  //   [session]
  // );

  const selectedScreensPerToggle = useMemo(() => screenList, [screenList]);

  const logInfo = useMemo(() => {
    if (!isAppLogEnabled)
      return 'App logs has been disabled in the app settings page';
    if (sessionLogs.length < 1)
      return 'App logs are not recorded due to old sdk versions';
    return null;
  }, [isAppLogEnabled, sessionLogs]);

  const excludedScreenList = useMemo(
    () =>
      selectedScreens.length && skipDeselectedToggle
        ? uniq(
            screens
              .filter(
                ({ activityName: activityNmm }) =>
                  !selectedScreens.includes(activityNmm)
              )
              .map((v) => v.activityName)
          )
        : [],
    [screens, selectedScreens, skipDeselectedToggle]
  );
  const selectedScreensMap = useMemo(
    () =>
      selectedScreensPerToggle.reduce((acc, screen) => {
        acc[screen] = excludedScreenList.length
          ? !excludedScreenList.includes(screen)
          : true;
        return acc;
      }, {}),
    [selectedScreensPerToggle, excludedScreenList]
  );

  const gestureActivities = React.useMemo(() => {
    const actions = [];
    const data = sessionDetail?.screenTimeline?.activities;

    if (data && screens) {
      data?.forEach((el) => {
        el.actions.forEach((action) => {
          if (action.name === 'UI Freeze' || action.isRage) {
            actions.push(action);
          }
        });
      });
    }

    return actions;
  }, [sessionDetail, screens]);

  const isWebHeatmaps = useMemo(() => parentType === 'webHeatmaps', [parentType]); 

  useEffect(() => {
    autoPlayRef.current = autoPlay;
    if (videoState !== 'pending' && !isWebHeatmaps) {
      window.location.hash = '';
    }
  }, [videoState, autoPlay, isWebHeatmaps]);

  useEffect(() => {
    if (videoState === 'ready' && isPlayable && videoPlaying) {
      dispatch(
        trackPageViews(null, {
          eventName: 'session_replay_started',
          track_type: 'event',
          eventProperty: {
            sessionid,
            startTime: videoRef?.current?.currentTime,
            duration: videoRef?.current?.duration,
            sidebar: selectedTab,
            markers: !!gestureActivities?.length,
            markersFeatureFlag: true,
            filter: removeValuesFromFilters(sessionSegment),
            downloadDate: sessionDetail?.time?.sessionUploadedDateTime,
            ...(parentType === 'heatmapsList' && { screenname }),
            ...(selectedTab === 'logs' && { logAvailable: isAppLogEnabled }),
            ...(selectedTab === 'logs' && { description: logInfo || '' }),
            ai_analyzed: sessionDetail?.sessionanalyzedbyai
          },
        })
      );
    }
  }, [
    dispatch,
    isAppLogEnabled,
    sessionDetail,
    logInfo,
    parentType,
    screenname,
    selectedTab,
    sessionid,
    videoPlaying,
    videoState,
    gestureActivities,
    sessionSegment,
  ]);

  const { _id: sessionDetailId } = session || {};

  useEffect(() => {
    if (
      sessionDetailId &&
      (!session?.isPlayable || session?.verifiedPastVideoRecordingLimit)
    ) {
      setVideoLimitPopup(true);
      rewind(0);
      videoRef?.current?.pause();
    }
  }, [videoState, videoPlaying, videoRef?.current?.currentTime]);
  const {
    timeRef,
    setPlaybackRate,
    playbackRateRef,
    skipInactivity,
    phoneFrame,
    videoElemRef,
    setCurrentScreen,
    setPlaying,
  } = useSessionVideoControlls();

  const skipInactivityRef = useRef(skipInactivity);

  useEffect(() => {
    skipInactivityRef.current = skipInactivity;
  }, [skipInactivity]);

  const resetVideo = useCallback(() => {
    currentScreenRef.current = undefined;
    setVideoState('pending');
    setPlaybackRate(1);
    setUserTime(0);
  }, []);

  useEffect(() => {
    resetVideo();
  }, [urlQuery?.sessionid]);

  const noVideoMessage = useMemo(() => session.noVideoMessage, [session]);
  const sharedSessionApp = queryClient.getQueryData('get-details');
  const isFreePlan = useMemo(
    () =>
      planType?.toLowerCase() === 'free' || sharedSessionApp?.data?.free_plan,
    [planType, sharedSessionApp?.data?.free_plan]
  );

  const overlay = useMemo(
    () => session.screenTimeline.overlay.sort((o1, o2) => o1.start - o2.start),
    [session]
  );
  const deviceHeight = useMemo(() => session?.device?.deviceHeight, [session]);

  const activityColorMap = useMemo(
    () =>{
     if( getScreenLayoutData(parentType).isSequentialTimelineColor ){
       return screens.reduce((acc, item, index ) => {
          acc[index] = timeLineSequentialColor(index)
          return acc
       }, {});
     }
     return Array.from(
        new Set(screens.map(({ activityName }) => activityName))
      ).reduce((acc, activityName) => {
        acc[activityName] = timeLineRandomColor(activityName);
        return acc;
      }, {})
  }, [getScreenLayoutData, parentType, screens]);
  const webReplayResizeFn = useCallback( ( h, w, observer ) => {

    const contentRefElem = containerRef.current;

    if ( !contentRef ) {

      return

    }

    const scaleContainer = scalledContainerRef.current;

    if ( !scaleContainer ) {

      return

    }

    const iframe = scaleContainer.querySelector( 'iframe' )
    const canvas = scaleContainer.querySelector( 'canvas' )

    if ( !iframe ) {
      return
    }

    if ( !canvas ) {
      return
    }

    if (!videoElemRef.current) {
      return;
    }

    const { videoWidth, videoHeight } = videoElemRef.current;

    const {

      width,

      height

    } = contentRefElem.getBoundingClientRect()

    // in case element is not painted, retrigger the observer

    if (!width && observer && contentRefElem) {

      observer.disconnect(contentRefElem);

      setTimeout(() => {

        observer.observe(contentRefElem);

      });

      return;

    }

    const hRatio = ( width - 48 ) / videoWidth;

    const vRatio = ( height - 48 ) / videoHeight;

    const ratio = Math.min(hRatio, vRatio);

    const rotate = 0

    const scale = ratio;

    iframe.style.transition = `transform 0.4s linear`;

    iframe.style.transform = `scale( ${scale} ) rotate( ${rotate} )`;

    canvas.style.transition = `transform 0.4s linear`;

    canvas.style.transform = `scale( ${scale} ) rotate( ${rotate} )`;

  }, [ videoElemRef ] )

  useEffect(() => {
    if (noVideoMessage) {
      setVideoState('videoError');
      if (isFreePlan) return;
      if (noVideoMessage.includes('not uploaded yet')) {
        dispatch(
          trackPageViews(null, {
            eventName: 'session_not_uploaded',
            track_type: 'event',
            pageName: parentType,
            eventProperty: {},
          })
        );
      }
    }
  }, [dispatch, isFreePlan, noVideoMessage, parentType]);

  const orientationOverlays = useMemo(() => {
    const duration = session.activity.totalSessionTime;
    return createOrientationOverlays(overlay, duration);
  }, [overlay, session]);

  const initialOrientation = useMemo(() => {
    const initialTime = parseFloat(defaultStartTime) || 0;
    const initialOverlay =
      findOrientationOverlayByTime(orientationOverlays, initialTime) ||
      orientationOverlays[0];
    return initialOverlay ? initialOverlay.o : 1;
  }, [overlay, defaultStartTime, orientationOverlays]);

  const [orientation, setOrientation] = useState(initialOrientation);

  const useRotation = useMemo(() => {

    if ( isWebSDK ) { return 0 }

    const {
      device: { deviceType },
    } = session;
    const useDeviceType = deviceType.toLowerCase();

    switch (useDeviceType) {
      case 'phone':
      case 'tablet': {
        return -90 * (orientation === 0 || orientation === 2);
      }
      case 'iphone':
      case 'ipad': {
        switch (orientation) {
          case 0: {
            return -90;
          }
          case 1: {
            return 0;
          }
          case 2: {
            return 90;
          }
          case 3: {
            return -180;
          }
          default: {
            return 180;
          }
        }
      }
      default: {
        console.warn('Unexpected device type');
        return 0
      }
    }
  }, [orientation, session, isWebSDK ]);

  const videoResizeFn = useCallback( ( h, w, observer, t ) => {
    const scaleContainer = scalledContainerRef.current;
    const container = containerRef.current;
    const target = t || container;
    const portraitMode = useRotation === 0 || useRotation === 180 || useRotation === -180;
    const reversedPortraitMode = useRotation === -180
    const videoElem = videoElemRef.current;

    const { videoWidth, videoHeight } = videoElem;
    const useVideoWidth = portraitMode ? videoWidth : videoHeight;
    const useVideoHeight = portraitMode ? videoHeight : videoWidth;
    const gestureWrapper = target.querySelector(
      `.${GestureWrapperClassName}`
    );

    const height = h || container?.getBoundingClientRect().height;
    const width = w || container?.getBoundingClientRect().width;

    // in case element is not painted, retrigger the observer
    if (!width && observer && container) {
      observer.disconnect(container);
      setTimeout(() => {
        observer.observe(container);
      });
      return;
    }

    const hRatio = width / useVideoWidth;
    const vRatio = height / useVideoHeight;

    const ratio = Math.min(hRatio, vRatio);
    const useWidth = videoWidth * ratio;
    const useHeight = videoHeight * ratio;
    const scale = Math.max(
      (useVideoWidth * ratio - 48) / width,
      (useVideoHeight * ratio - 48) / height
    );

    const rotateDeg = ( portraitMode ? 0 : -90 ) + ( reversedPortraitMode ? -180 : 0 );
    const rotate = `${rotateDeg}deg`;

    if (scaleContainer?.style) {
      scaleContainer.style.transition = `transform 0.4s linear`;
      scaleContainer.style.width = `${useWidth}px`;
      scaleContainer.style.height = `${useHeight}px`;
      scaleContainer.style.transform = `translate(-50%, -50%) scale( ${scale} ) rotate( ${rotate} )`;
    }

    // scale gestures
    if (gestureWrapper) {
      const scaleGestureWrapper = useWidth / videoWidth;
      gestureWrapper.style.transform = `scale( ${scaleGestureWrapper} ) translate( -50%, -50% )`;
      gestureWrapper.style.setProperty(
        '--video-scale',
        1 / scaleGestureWrapper
      );
    }
  }, [ useRotation, videoElemRef ] )

  useEffect(() => {
    if ( !videoRef ) return
    const videoElem = videoRef.current;
    const videoContainer = videoContainerRef.current;
    videoElemRef.current = videoElem;

    if (video && videoElem) {
      if ( !isWebSDK || isFlutterWeb ) {
        const gesturesOverlay = new SessionGestures({
          gestures: overlay,
          video: videoElem,
          session,
          screens,
          container: videoContainer,
          skipInactivity: skipInactivityRef.current,
          videoResizeFn,
          isFlutterWeb,
        });
        videoGestures.current = gesturesOverlay;
      }

      videoElem.playbackRate = playbackRateRef.current;

      const handleClick = () => {
        if (videoElem.paused) {
          videoElem.play().catch( () => null );
        } else {
          videoElem.pause();
        }
      };

      const handleMetaLoaded = () => {
        setVideoState('ready');
        if (autoPlayRef.current) {
          videoElem.play().catch( () => null );
        }
      };

      const handleError = ( e ) => {
        const mediaError = videoElem?.error;
        const videoSrc = videoElem?.src || videoElem?.currentSrc || '';
        
        const getMediaErrorType = (code) => {
          switch (code) {
            case 1: return 'MEDIA_ERR_ABORTED - Playback aborted by user';
            case 2: return 'MEDIA_ERR_NETWORK - Network error occurred';
            case 3: return 'MEDIA_ERR_DECODE - Decode error occurred';
            case 4: return 'MEDIA_ERR_SRC_NOT_SUPPORTED - Media format not supported';
            default: return 'Unknown error code';
          }
        };

        const errorContext = {
          sessionId: sessionid,
          videoUrl: videoSrc,
          userAgent: navigator.userAgent,
          timestamp: new Date().toISOString(),
          videoElement: {
            networkState: videoElem?.networkState,
            readyState: videoElem?.readyState,
            currentTime: videoElem?.currentTime,
            duration: videoElem?.duration,
            videoWidth: videoElem?.videoWidth,
            videoHeight: videoElem?.videoHeight,
            buffered: videoElem?.buffered?.length ? {
              start: videoElem.buffered.start(0),
              end: videoElem.buffered.end(videoElem.buffered.length - 1)
            } : null,
            seekable: videoElem?.seekable?.length ? {
              start: videoElem.seekable.start(0),
              end: videoElem.seekable.end(videoElem.seekable.length - 1)
            } : null
          },
          mediaError: mediaError ? {
            code: mediaError.code,
            message: mediaError.message,
            type: getMediaErrorType(mediaError.code)
          } : null,
          domEvent: {
            type: e.type,
            isTrusted: e.isTrusted,
            target: e.target ? e.target.tagName : null
          },
          session: {
            isPlayable: session?.isPlayable,
            deviceType: session?.device?.deviceType,
            platform: session?.device?.platform
          }
        };

        rollbar.error('Video playback error', e, errorContext);
        
        setVideoState('videoError');

        const source = videoElem?.src || ''
        let code = ''
        let message = ''

        if ( source.error ) {
          code = source.error.code
          message = source.error.message
          
          rollbar.error( 'Source video error', e, {
            source,
            error: e.toString(),
            code,
            message,
          } )
        }

      };

      const handleRateChange = (e) => {
        setPlaybackRate(e.currentTarget.playbackRate);
      };

      const handleOrientationCheck = (e) => {
        const { currentTime } = e.currentTarget;

        const currentOverlay = findOrientationOverlayByTime(
          orientationOverlays,
          currentTime
        );

        if (currentOverlay) {
          setOrientation(currentOverlay.o);
        }
      };

      const handlePlay = () => {
        if (autoPlayRef.current && session?.isPlayable) {
          dispatch(
            fetchPlanHatApi({
              action: `Played video on ${mappedSegmentType[parentType]}`,
            })
          );
          videoElem.play().catch( () => null );
        }
        setPlaying(true);
      };

      const handePause = () => {
        setPlaying(false);
      };

      videoElem.addEventListener('click', handleClick);
      videoElem.addEventListener('loadedmetadata', handleMetaLoaded, false);
      videoElem.addEventListener('error', handleError, false);
      videoElem.addEventListener('ratechange', handleRateChange, false);
      videoElem.addEventListener('timeupdate', handleOrientationCheck);
      videoElem.addEventListener('play', handlePlay);
      videoElem.addEventListener('pause', handePause);

      // If metadata already loaded before listeners were attached, handle it now
      if (videoElem.readyState >= 1) {
        handleMetaLoaded();
      }

      // eslint-disable-next-line consistent-return
      return () => {
        videoElem.removeEventListener('click', handleClick);
        videoElem.removeEventListener(
          'loadedmetadata',
          handleMetaLoaded,
          false
        );
        videoElem.removeEventListener('error', handleError, false);
        videoElem.removeEventListener('ratechange', handleRateChange, false);
        videoElem.removeEventListener('timeupdate', handleOrientationCheck);
        videoElem.removeEventListener('play', handlePlay);
        videoElem.removeEventListener('pause', handePause);

        setPlaying(false);
        currentScreenRef.current = null;
        setCurrentScreen(null);
        timeRef.current = 0;

        if (videoGestures.current) {
          videoGestures.current.destroy();
          videoGestures.current = null;
        }
      };
    }

    // eslint-disable-next-line consistent-return
    return () => {
      currentScreenRef.current = null;
      setCurrentScreen(null);
      timeRef.current = 0;
    };
  }, [
    isWebSDK,
    isFlutterWeb,
    video,
    screens,
    overlay,
    deviceHeight,
    session,
    videoElemRef,
    sessionDetail,
    orientationOverlays,
    videoRefLoaded,
    sessionid,
    dispatch, 
    parentType, 
    playbackRateRef, 
    setCurrentScreen, 
    setPlaybackRate, 
    setPlaying, 
    timeRef, 
    videoResizeFn
  ]);

  // eslint-disable-next-line consistent-return
  useEffect(() => {
    const videoElem = videoElemRef.current;
    if (videoElem) {
      const handleVideoTimeOnceReady = () => {
        const parsedTime = parseFloat(defaultStartTime) || 0;
        if (!initdoneRef.current) {
          const time = parsedTime === 0 ? 0.01 : parsedTime; // setting static initial time to 0.01 to avoid video not playing
          if (Number.isFinite(time)) {
            videoElem.currentTime = time;
          }
          initdoneRef.current = true;
        }
      };

      videoElem.addEventListener('canplaythrough', 
        handleVideoTimeOnceReady);

      return () => {
        videoElem.removeEventListener(
          'canplaythrough',
          handleVideoTimeOnceReady
        );
        initdoneRef.current = false;
      };
    }
  }, [defaultStartTime, videoElemRef]);

  useEffect(() => {
    const gesturesOverlay = videoGestures.current;

    if (gesturesOverlay) {
      gesturesOverlay.setSkipInactivity(skipInactivity);
    }
  }, [skipInactivity]);

  useTimeTracker(
    () => {
      setUserTime(userTime + 1);
    },
    videoPlaying ? TIMER_DELAY : null
  );

  // A session with no video has nothing to load. Derive this from the payload rather than
  // from videoState alone: the reset effect keyed on the URL sessionid can run after the
  // noVideoMessage effect and park videoState in 'pending' with nothing left to move it.
  const hasNoVideo = !video && !!noVideoMessage;
  const loaderVisible = videoState === 'pending' && !hasNoVideo;
  const videoVisible = videoState === 'ready';
  const errorVisible = videoState === 'videoError' || hasNoVideo;

  useEffect(() => {
    const videoElem = videoElemRef.current;
    const container = containerRef.current;
    const scaleContainer = scalledContainerRef.current;

    if (container && videoElem && scaleContainer) {
      const observer = new ResizeObserver(
        ([
          {
            target,
            contentRect: { width, height },
          },
        ]) => {
          if ( isWebSDK && !isFlutterWeb ) {
            return webReplayResizeFn( height, width, observer )
          }
          return videoResizeFn( height, width, observer, target )
        }
      );

      const handleLoadMetaData = () => {
        observer.observe(container);
      };

      // pause and rewind 5s
      const handleKeyDown = (event) => {
        // do nothing if element is an input/textarea
        if (
          typeof document.activeElement.readOnly === 'boolean' &&
          document.activeElement.id !== 'timeline-slider'
        ) {
          return undefined;
        }

        switch (event.code) {
          case 'Space': {
            event.preventDefault();
            if (
              sessionDetailId &&
              (!session?.isPlayable || session?.verifiedPastVideoRecordingLimit)
            ) {
              !videoLimitPopup && setVideoLimitPopup(!videoLimitPopup);
              return undefined;
            }
            return videoElem.paused ? videoElem.play().catch( () => null ) : videoElem.pause();
          }
          case 'ArrowLeft': {
            event.preventDefault();
            const newTime = videoElem.currentTime - 5;
            if (Number.isFinite(newTime)) {
              videoElem.currentTime = newTime;
            }
            return undefined;
          }
          case 'ArrowRight': {
            event.preventDefault();
            const newTime = videoElem.currentTime + 5;
            if (Number.isFinite(newTime)) {
              videoElem.currentTime = newTime;
            }
            return undefined;
          }
          default: {
            return undefined;
          }
        }
      };

      const handleContentResize = () => {
        if ( isWebSDK && !isFlutterWeb ) {
          const element = containerRef.current;
          if (!element) return;
          const { width, height } = element.getBoundingClientRect() || {};
          webReplayResizeFn( height, width, observer )
        }
      }

      document.addEventListener('keydown', handleKeyDown);

      videoElem.addEventListener( 'contentresize', handleContentResize );

      if (!videoElem.videoWidth) {
        videoElem.addEventListener('loadedmetadata', handleLoadMetaData);
      } else {
        observer.observe(container);
      }

      return () => {
        observer.disconnect();
        videoElem.removeEventListener( 'contentresize', handleContentResize );
        document.removeEventListener('keydown', handleKeyDown);
        videoElem.removeEventListener('loadedmetadata', handleLoadMetaData);
      };
    }

    return undefined;
  }, [useRotation, videoResizeFn, isWebSDK, webReplayResizeFn, videoRefLoaded, isFlutterWeb]);

  useEffect(() => {
    if (!prevSessionIdRef.current || prevSessionIdRef.current !== sessionid) {
      if (sessionQueriesToInvalidate.length) {
        sessionQueriesToInvalidate.forEach((query) => {
          queryClient.refetchQueries([query]);
        });
        setSessionQueriesToInvalidate([]);
      }
      prevSessionIdRef.current = sessionid;
    }
  }, [
    sessionid,
    queryClient,
    sessionQueriesToInvalidate,
    setSessionQueriesToInvalidate,
  ]);

  return (
    <>
      {
        showWebReplayUrl ? (
          <WebReplayUrl
            replayInstanceRef={ isWebSDK ? videoRef : undefined }
            urlTimeline={ isFlutterWeb ? flutterUrlTimeline : undefined }
            videoRef={ isFlutterWeb ? videoRef : undefined }
          />
        ) : null
      }
      {isLastSelectedScreen.flag && (
        <LastScreenMessageStyled>
          <a
            className={classNames('last-key-message', {
              'screen-unseleced-message':
                isLastSelectedScreen.message.length > 39,
            })}
            href="#!"
          >
            <InfoCircleOutlined /> {isLastSelectedScreen.message}
          </a>
        </LastScreenMessageStyled>
      )}
      <Container
        key="video-container"
        isFaded={
          isLastSelectedScreen.flag && isLastSelectedScreen.message.length > 39
        }
      >
        <TopContainer ref={containerRef} key="top-container">
          <LoaderContainer aria-hidden={!loaderVisible || !session?.isPlayable}>
            <ReactLoader fullscreen />
          </LoaderContainer>
          <ErrorContainer aria-hidden={!errorVisible}>
            <ErrorMessage>
              {noVideoMessage ? (
                <p dangerouslySetInnerHTML={{ __html: noVideoMessage }} />
              ) : (
                <p>We encounter an error while playing the video</p>
              )}
            </ErrorMessage>
          </ErrorContainer>
          <VideoContainer ref={ contentRef } aria-hidden={!videoVisible && session?.isPlayable}>
            {video || !session?.isPlayable ? (
              <>
                <ScaledContainer
                  initialRotation={useRotation}
                  ref={scalledContainerRef}
                >
                  {
                    isSessDataLoaded ? (

                      isFlutterWeb ? (
                        <PhoneFrame data-frameon={phoneFrame}>
                          <VideoOverlayContainer>
                            <VideoInner blurBackground={blurBackground}>
                              <Video
                                data-uxc="obfuscated"
                                ref={videoRef}
                                src={`${video}#t=0.000000001`}
                                preload="auto"
                                autoPlay={autoPlay}
                              />
                            </VideoInner>
                            <OverlayContainer ref={videoContainerRef} />
                          </VideoOverlayContainer>
                        </PhoneFrame>
                      ) : isWebSDK ? (
                        <WebReplay
                          key={ video }
                          src={video}
                          autoPlay={autoPlay}
                          videoRef={ videoRef }
                          skipInactivity={skipInactivity}
                          data-uxc="obfuscated"
                        />
                      ) : (
                        <PhoneFrame data-frameon={phoneFrame}>
                          <VideoOverlayContainer>
                            <VideoInner blurBackground={blurBackground}>
                              <Video
                                data-uxc="obfuscated"
                                ref={ videoRef }
                                src={`${video}#t=0.000000001`}
                                preload="auto"
                                autoPlay={autoPlay}
                              />
                            </VideoInner>
                            <OverlayContainer ref={videoContainerRef} />
                          </VideoOverlayContainer>
                        </PhoneFrame>
                      )
                    ) : null
                  }
                </ScaledContainer>
                <SkippedVideoLabel ref={skippedLabelStyleRef}>
                  <SkipIcon />
                  <div className="skipped-video-label" ref={skippedLabel} />
                </SkippedVideoLabel>
              </>
            ) : (
              <VideoError>
                <WarningOutlined style={{ marginRight: '10px' }} />
                <VideoErrorText>{session.noVideoMessage}</VideoErrorText>
              </VideoError>
            )}
          </VideoContainer>
        </TopContainer>
        {video && (
          <VideoControls
            key={ videoRefLoaded }
            appId={appId}
            videoRef={videoRef}
            toggleFullScreen={toggleFullScreen}
            session={session}
            screens={screens}
            selectedScreensMap={selectedScreensMap}
            activityColorMap={activityColorMap}
            isShareSession={urlQuery.shareSessionKey}
            skippedLabelRef={skippedLabel}
            excludedScreenList={excludedScreenList}
            multiScreenSkippedData={multiScreenSkippedData}
            skippedLabelStyleRef={skippedLabelStyleRef}
          />
        )}
      </Container>
    </>
  );
};

export default memo(SessionVideo);
