function SkipInactivitySwitch({
    skipInactivity,
    toggleSkipInactivity,
}: {
    skipInactivity: boolean;
    toggleSkipInactivity: () => void;
}) {
    const {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        urlReducer: urlQuery,
      } = useSelector((state) => state);

    const { getScreenLayoutData } = useScreenLayoutContext();
    if (getScreenLayoutData(urlQuery?.parentType).isNewVideoControls) {
        return (
            <Tooltip
                title={skipInactivity ? "Inactivity Skipped" : "Skip Inactivity"}
                placement="top"
                arrowPointAtCenter
                autoAdjustOverflow={false}
            >
                <CustomSwitch checked={skipInactivity} onChange={toggleSkipInactivity} />
            </Tooltip>)
    }
    return (
        <PillButton
            onClick={toggleSkipInactivity}
            aria-checked={skipInactivity}
            data-intercom-target="Skip inactivity"
        >
            Skip Inactivity: {skipInactivity ? 'On' : 'Off'}
            <PillButtonIcon
                src="/static/sessions/timeline/forward.svg"
                alt=""
            />
        </PillButton>

    )
}

export default SkipInactivitySwitch