import React from 'react'
import styled from 'styled-components'
import { theme } from 'theme'
import SessionReplay from './SessionReplay'

const UrlContainer = styled.div`
	display: flex;
	justify-content: flex-start;
	align-items: center;
	background: #fff;
	height: 34px;
	position: relative;
	border-radius: 4px 4px 0 0;
	gap: 10px;
	z-index: 2;
	width: 100%;
	padding: ${ theme.spacing( 0, 2 ) };
	&[aria-hidden='true'] {
		visibility: hidden;
	}
`

const Url = styled.div`
	display: flex;
	border-radius: 4px;
	flex: 1;
	gap: 4px;
	background: ${ theme.colors.surface05.toString() };
	padding: 2px 6px;
	font-size: ${ theme.fontSize( 1.2 ) };
	color: ${ theme.colors.surface400.toString() };
	width: auto;
	max-width: 100%;
	overflow: hidden;
	span {
		white-space: nowrap;
		overflow: hidden;
		text-overflow: ellipsis;
		max-width: 100%;
	}
`

const WebIcon = styled.img`
`

const ActionIcon = styled.img`
	width: 16px;
	height: 16px;
`

const ActionButton = styled.button`
	display: flex;
	align-items: center;
	justify-content: center;
	border: none;
	background: none;
	padding: 0;
	transition: background 0.2s;
	border-radius: 2px;
	&:hover {
		cursor: pointer;
		background: ${ theme.colors.surface10.toString() };
	}
`

const Actions = styled.div`
	display: flex;
	gap: ${ theme.spacing( 1 ) };
`

const Placeholder = styled.div`
	width: 40px;
`


export type UrlTimelineEntry = {
	time: number;
	url: string;
}

// eslint-disable-next-line arrow-body-style
const WebReplayUrl: React.FC<{
	replayInstanceRef?: React.MutableRefObject<SessionReplay | undefined>;
	urlTimeline?: UrlTimelineEntry[];
	videoRef?: React.MutableRefObject<HTMLVideoElement | undefined>;
}> = ( {
	replayInstanceRef,
	urlTimeline,
	videoRef,
} ) => {

	const isTimelineMode = Array.isArray( urlTimeline ) && urlTimeline.length > 0

	const [ replayInstance, setReplayInstance ] = React.useState<SessionReplay>()
	const [ url, setUrl ] = React.useState<string>()

	React.useEffect( () => {
		if ( isTimelineMode ) { return }
		if ( replayInstanceRef?.current ) {
			setReplayInstance( replayInstanceRef.current )
			return
		}
		if ( !replayInstanceRef?.current ) {
			// eslint-disable-next-line no-undef
			let timeout: NodeJS.Timeout | null = null
			const check = () => {
				if ( replayInstanceRef?.current ) {
					setReplayInstance( replayInstanceRef.current )
					return
				}
				timeout = setTimeout( check, 100 )
			}
			timeout = setTimeout( check, 100 )

			// eslint-disable-next-line consistent-return
			return () => {
				if ( timeout ) {
					clearTimeout( timeout )
				}
			}
		}
	}, [ replayInstanceRef, isTimelineMode ] )

	React.useEffect( () => {
		if ( !isTimelineMode || !urlTimeline ) { return }

		const sorted = [ ...urlTimeline ].sort( ( a, b ) => a.time - b.time )

		const pickUrl = ( currentTime: number ) => {
			let match: UrlTimelineEntry | undefined
			for ( let i = 0; i < sorted.length; i += 1 ) {
				const entry = sorted[ i ]
				if ( entry.time <= currentTime ) {
					match = entry
				} else {
					break
				}
			}
			const next = match ?? sorted[ 0 ]
			if ( !next ) { return }
			setUrl( next.url )
		}

		pickUrl( videoRef?.current?.currentTime ?? 0 )

		const videoElem = videoRef?.current
		if ( !videoElem ) { return }

		const handleTimeUpdate = () => {
			pickUrl( videoElem.currentTime )
		}

		videoElem.addEventListener( 'timeupdate', handleTimeUpdate )
		videoElem.addEventListener( 'seeked', handleTimeUpdate )

		// eslint-disable-next-line consistent-return
		return () => {
			videoElem.removeEventListener( 'timeupdate', handleTimeUpdate )
			videoElem.removeEventListener( 'seeked', handleTimeUpdate )
		}
	}, [ isTimelineMode, urlTimeline, videoRef ] )

	const getCurrentUrl = React.useCallback( () => {
		if ( isTimelineMode ) { return url }
		return replayInstance?.getUrl()
	}, [ isTimelineMode, url, replayInstance ] )

	const handleOpenInNewTab = React.useCallback( () => {
		const currentUrl = getCurrentUrl()
		if ( !currentUrl ) { return }
		if ( !currentUrl.startsWith( 'http:' ) && !currentUrl.startsWith( 'https:' ) ) { return }
		window.open( currentUrl, '_blank' )
	}, [ getCurrentUrl ] )

	const handleCopyLink = React.useCallback( () => {
		const currentUrl = getCurrentUrl()
		if ( !currentUrl ) { return }
		if ( !currentUrl.startsWith( 'http:' ) && !currentUrl.startsWith( 'https:' ) ) { return }
		navigator.clipboard.writeText( currentUrl )
	}, [ getCurrentUrl ] )

	React.useEffect( () => {
		if ( isTimelineMode ) { return }
		if ( !replayInstance ) { return }
		replayInstance.addEventListener( 'urlchange', () => {
			// eslint-disable-next-line no-shadow
			const url = replayInstance.getUrl()
			if ( !url ) { return }
			if ( !url.startsWith( 'http:' ) && !url.startsWith( 'https:' ) ) {
				setUrl( 'N/A' )
				return
			}
			setUrl( url )
		} )
	}, [ replayInstance, isTimelineMode ] )

	const isReady = isTimelineMode ? !!url : ( !!replayInstance && !!url )

	return (
		<UrlContainer
			aria-hidden={ !isReady }
		>
			{/* <Placeholder /> */}
			<Url>
				<WebIcon src="/static/web.svg" />
				<span
					title={ url }
				>
					{ url }
				</span>
			</Url>
			<Actions>
				<ActionButton
					type="button"
					aria-label="Open in new tab"
					onClick={ handleOpenInNewTab }
				>
					<ActionIcon src="/static/redirection.svg" />
				</ActionButton>
				<ActionButton
					type="button"
					aria-label='Copy link to clipboard'
					onClick={ handleCopyLink }
				>
					<ActionIcon src="/static/copy-link.svg" />
				</ActionButton>
			</Actions>
		</UrlContainer>
	)
}

export default React.memo( WebReplayUrl )